window.QUESTION_BANK = [{"id":"adenopatias-001","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cómo define la guía de 2023 una adenopatía?","respuesta":"Un ganglio anormal por su tamaño, consistencia, adherencia o cambios en los tejidos vecinos.","source":"Banco de preguntas validado"},{"id":"adenopatias-002","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"En un niño, ¿a partir de qué diámetro se considera aumentado un ganglio cervical?","respuesta":"Mayor de 1 cm.","source":"Banco de preguntas validado"},{"id":"adenopatias-003","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál es el límite de tamaño para considerar aumentado un ganglio cervical en un neonato?","respuesta":"Mayor de 0.5 cm.","source":"Banco de preguntas validado"},{"id":"adenopatias-004","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Qué término describe una adenopatía con signos inflamatorios, habitualmente secundaria a una infección bacteriana aguda?","respuesta":"Adenitis.","source":"Banco de preguntas validado"},{"id":"adenopatias-005","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál es la evolución característica de una adenopatía aguda?","respuesta":"Aparece en pocos días, disminuye antes de 2 semanas y desaparece en 3-4 semanas.","source":"Banco de preguntas validado"},{"id":"adenopatias-006","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Qué criterio define adenopatías generalizadas?","respuesta":"Afectación de dos o más regiones no contiguas.","source":"Banco de preguntas validado"},{"id":"adenopatias-007","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Un lactante presenta adenopatías cervicales que aparecieron hace 5 días, ya disminuyen de tamaño y no tienen signos inflamatorios. ¿Qué clasificación temporal corresponde?","respuesta":"Adenopatía aguda.","source":"Banco de preguntas validado"},{"id":"adenopatias-008","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Un escolar mantiene una adenopatía cervical durante 5 semanas. ¿Cuál es la clasificación más apropiada?","respuesta":"Adenopatía subaguda.","source":"Banco de preguntas validado"},{"id":"adenopatias-009","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un escolar mantiene una adenopatía cervical indolora durante 7 semanas. ¿Cómo se clasifica su evolución y qué exige este dato?","respuesta":"Adenopatía crónica; requiere reevaluación dirigida por causas específicas o de mayor gravedad. Adenopatías agudas: patrón viral y bacteriano","source":"Banco de preguntas validado"},{"id":"adenopatias-010","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál es la etiología más frecuente de las adenopatías cervicales agudas bilaterales?","respuesta":"Procesos reactivos a infecciones virales de vías respiratorias superiores.","source":"Banco de preguntas validado"},{"id":"adenopatias-011","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Qué características suelen tener los ganglios cervicales reactivos de origen viral?","respuesta":"Pequeños, móviles, bien delimitados, con pocos signos inflamatorios y sin supuración.","source":"Banco de preguntas validado"},{"id":"adenopatias-012","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Mencione un virus asociado a adenopatías cervicales agudas bilaterales.","respuesta":"Por ejemplo, adenovirus, rinovirus, enterovirus, influenza, parainfluenza, herpes simple, HHV-6, HHV-7, EBV o CMV.","source":"Banco de preguntas validado"},{"id":"adenopatias-013","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Qué etiología predomina en las adenopatías cervicales agudas unilaterales?","respuesta":"Bacteriana.","source":"Banco de preguntas validado"},{"id":"adenopatias-014","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"¿Qué combinación clínica orienta a adenitis bacteriana aguda?","respuesta":"Adenopatía unilateral con dolor, calor, eritema y fiebre.","source":"Banco de preguntas validado"},{"id":"adenopatias-015","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Cuál es el rango de tamaño que pueden alcanzar las adenopatías bacterianas cervicales agudas?","respuesta":"Aproximadamente 2-6 cm.","source":"Banco de preguntas validado"},{"id":"adenopatias-016","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Qué hallazgo clínico sugiere evolución de una adenitis bacteriana hacia absceso?","respuesta":"Fluctuación.","source":"Banco de preguntas validado"},{"id":"adenopatias-017","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Un niño con rinorrea y tos presenta ganglios cervicales pequeños, bilaterales, móviles y no dolorosos. ¿Cuál es la conducta inicial más coherente?","respuesta":"Observación y tratamiento sintomático, por probable adenopatía viral/reactiva.","source":"Banco de preguntas validado"},{"id":"adenopatias-018","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Un niño con dolor dental, fiebre y masa submandibular unilateral, caliente y eritematosa, presenta el patrón más compatible con:","respuesta":"Adenitis bacteriana aguda, considerando anaerobios por el foco odontológico.","source":"Banco de preguntas validado"},{"id":"adenopatias-019","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un preescolar con faringitis viral tiene adenopatías cervicales bilaterales que no supuran. ¿Qué dato clínico favorece una etiología viral frente a bacteriana?","respuesta":"La bilateralidad con ganglios pequeños, móviles y pocos signos inflamatorios.","source":"Banco de preguntas validado"},{"id":"adenopatias-020","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un escolar presenta adenopatía cervical unilateral de 4 cm, dolorosa, con eritema y fiebre. ¿Cuál complicación debe buscarse de forma dirigida?","respuesta":"Absceso ganglionar con fluctuación.","source":"Banco de preguntas validado"},{"id":"adenopatias-021","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En un niño con adenitis unilateral y mala higiene oral, ¿por qué no basta considerar solo S. aureus y S. pyogenes?","respuesta":"Porque la enfermedad periodontal o la mala higiene oral aumentan la probabilidad de bacterias anaerobias.","source":"Banco de preguntas validado"},{"id":"adenopatias-022","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un paciente tiene adenopatías bilaterales de 1.5 cm y fiebre baja durante un cuadro respiratorio alto. No hay eritema ni limitación de movilidad. ¿Cuál es la hipótesis inicial más probable?","respuesta":"Adenopatías reactivas de etiología viral. Adenopatías subagudas y crónicas","source":"Banco de preguntas validado"},{"id":"adenopatias-023","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál es el agente causal de la enfermedad por arañazo de gato?","respuesta":"Bartonella henselae.","source":"Banco de preguntas validado"},{"id":"adenopatias-024","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Qué microorganismos deben considerarse en una adenopatía cervical crónica además de Bartonella?","respuesta":"Mycobacterium tuberculosis y micobacterias no tuberculosas.","source":"Banco de preguntas validado"},{"id":"adenopatias-025","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿En qué grupo etario son más típicas las adenopatías por micobacterias no tuberculosas?","respuesta":"Niños menores de 5 años.","source":"Banco de preguntas validado"},{"id":"adenopatias-026","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un niño presenta adenopatía regional subaguda tras contacto con un gato. ¿Qué agente debe sospecharse primero?","respuesta":"Bartonella henselae.","source":"Banco de preguntas validado"},{"id":"adenopatias-027","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Un preescolar presenta una adenopatía cervical unilateral, firme, indolora y progresiva, con piel violácea. ¿Cuál es la etiología más sugerente?","respuesta":"Micobacterias no tuberculosas.","source":"Banco de preguntas validado"},{"id":"adenopatias-028","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Qué evolución cutánea puede presentar una adenopatía por micobacterias no tuberculosas?","respuesta":"Fistulización.","source":"Banco de preguntas validado"},{"id":"adenopatias-029","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Por qué una adenopatía persistente no debe asumirse como reactiva sin reevaluación?","respuesta":"Porque las formas subagudas y crónicas pueden corresponder a agentes infecciosos específicos o a otras causas que requieren estudio.","source":"Banco de preguntas validado"},{"id":"adenopatias-030","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un niño menor de 5 años tiene una masa cervical indolora de crecimiento lento y piel violácea, sin cuadro respiratorio agudo. ¿Cuál es el siguiente planteamiento diagnóstico?","respuesta":"Considerar micobacterias no tuberculosas y ampliar el estudio dirigido.","source":"Banco de preguntas validado"},{"id":"adenopatias-031","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un adolescente tiene adenopatía regional de 4 semanas y antecedente de arañazo de gato. ¿Qué diagnóstico integra mejor el cuadro?","respuesta":"Enfermedad por arañazo de gato por Bartonella henselae.","source":"Banco de preguntas validado"},{"id":"adenopatias-032","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un paciente con adenopatía cervical de más de 6 semanas y contacto con tuberculosis requiere una evaluación dirigida. ¿Qué posibilidad infecciosa debe priorizarse?","respuesta":"Tuberculosis ganglionar. Localización y orientación etiológica","source":"Banco de preguntas validado"},{"id":"adenopatias-033","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Qué localización ganglionar tiene especial importancia por su alta asociación con malignidad?","respuesta":"Supraclavicular.","source":"Banco de preguntas validado"},{"id":"adenopatias-034","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Con qué procesos se relacionan con frecuencia las adenopatías cervicales?","respuesta":"Infecciones respiratorias, faringitis, infecciones odontológicas, EBV y CMV.","source":"Banco de preguntas validado"},{"id":"adenopatias-035","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Qué causas se asocian típicamente con adenopatías occipitales?","respuesta":"Infecciones del cuero cabelludo, dermatitis, tiña o rubéola.","source":"Banco de preguntas validado"},{"id":"adenopatias-036","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Qué localización ganglionar puede aparecer con conjuntivitis, blefaritis o infecciones oculares?","respuesta":"Preauricular.","source":"Banco de preguntas validado"},{"id":"adenopatias-037","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"¿Qué procesos deben considerarse ante adenopatía mediastínica?","respuesta":"Leucemias, linfomas, neuroblastoma e infecciones crónicas.","source":"Banco de preguntas validado"},{"id":"adenopatias-038","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Qué causas se deben considerar ante adenopatías abdominales o pélvicas?","respuesta":"Adenitis mesentérica, infecciones, linfomas, neuroblastoma o tumor de Wilms.","source":"Banco de preguntas validado"},{"id":"adenopatias-039","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Qué suele orientar una adenopatía inguinal?","respuesta":"Lesiones o infecciones de extremidades inferiores o de la región genital.","source":"Banco de preguntas validado"},{"id":"adenopatias-040","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Un niño con tiña del cuero cabelludo presenta ganglios posteriores de la cabeza. ¿Qué localización se espera?","respuesta":"Occipital.","source":"Banco de preguntas validado"},{"id":"adenopatias-041","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Un niño con conjuntivitis y edema palpebral presenta adenopatía regional. ¿Cuál es la localización más probable?","respuesta":"Preauricular.","source":"Banco de preguntas validado"},{"id":"adenopatias-042","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un niño con una lesión infectada en la pierna presenta un ganglio palpable detrás de la rodilla. ¿Qué localización corresponde y qué sugiere?","respuesta":"Poplítea; orienta a infección cutánea de la extremidad inferior.","source":"Banco de preguntas validado"},{"id":"adenopatias-043","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un paciente con adenopatía supraclavicular debe evaluarse con prioridad. ¿Por qué?","respuesta":"Por su alta asociación con malignidad, además de tuberculosis e infecciones granulomatosas.","source":"Banco de preguntas validado"},{"id":"adenopatias-044","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un niño con adenopatía axilar y antecedente reciente de vacunación, sin síntomas sistémicos, tiene una asociación etiológica plausible con:","respuesta":"La vacunación reciente. Benignidad, malignidad y datos de alarma","source":"Banco de preguntas validado"},{"id":"adenopatias-045","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Qué consistencia y movilidad suelen tener los ganglios de características benignas?","respuesta":"Son blandos, móviles y bien delimitados.","source":"Banco de preguntas validado"},{"id":"adenopatias-046","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cómo suele comportarse en el tiempo una adenopatía benigna o reactiva?","respuesta":"Tiende a disminuir progresivamente.","source":"Banco de preguntas validado"},{"id":"adenopatias-047","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Qué característica de consistencia o adherencia aumenta la sospecha neoplásica?","respuesta":"Consistencia dura o fijación a planos profundos.","source":"Banco de preguntas validado"},{"id":"adenopatias-048","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Qué localización aislada constituye un dato de alarma para malignidad?","respuesta":"Supraclavicular.","source":"Banco de preguntas validado"},{"id":"adenopatias-049","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"¿Qué alteración hematológica o cutánea acompañante es un dato de alarma?","respuesta":"Alteraciones del hemograma o hematomas no traumáticos.","source":"Banco de preguntas validado"},{"id":"adenopatias-050","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Un niño tiene un ganglio cervical doloroso durante una faringitis aguda. ¿Por qué el dolor no implica por sí solo malignidad?","respuesta":"Porque el dolor es frecuente cuando existe inflamación aguda.","source":"Banco de preguntas validado"},{"id":"adenopatias-051","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Un adolescente presenta un ganglio duro, fijo, indoloro y de crecimiento progresivo. ¿Cuál es la principal preocupación diagnóstica?","respuesta":"Una causa neoplásica.","source":"Banco de preguntas validado"},{"id":"adenopatias-052","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Cómo cambia el enfoque una adenopatía generalizada sin causa evidente?","respuesta":"Debe hacer pensar en enfermedad sistémica y motivar ampliación del estudio.","source":"Banco de preguntas validado"},{"id":"adenopatias-053","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Un niño presenta adenopatía supraclavicular, pérdida de peso y sudoración. ¿Qué nivel de prioridad requiere?","respuesta":"Evaluación urgente por alta sospecha de enfermedad grave, incluida malignidad.","source":"Banco de preguntas validado"},{"id":"adenopatias-054","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un preescolar con adenopatía móvil y blanda asociada a infección respiratoria mejora progresivamente. ¿Qué elementos apoyan benignidad?","respuesta":"Movilidad, consistencia blanda, asociación con infección evidente y reducción progresiva.","source":"Banco de preguntas validado"},{"id":"adenopatias-055","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un niño con adenopatía cervical persistente desarrolla hematomas no traumáticos y hepatosplenomegalia. ¿Cuál es la conducta estratégica?","respuesta":"Ampliar estudios y derivar de forma prioritaria por sospecha de enfermedad hematológica o neoplásica.","source":"Banco de preguntas validado"},{"id":"adenopatias-056","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un paciente tiene síntomas respiratorios y sospecha de masa mediastínica junto con adenopatías. ¿Por qué este hallazgo requiere atención urgente?","respuesta":"Porque puede relacionarse con una masa mediastínica o enfermedad neoplásica y comprometer la vía respiratoria. Historia clínica, examen físico y estudios","source":"Banco de preguntas validado"},{"id":"adenopatias-057","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Qué dato temporal de la historia clínica es imprescindible registrar en un niño con adenopatía?","respuesta":"El tiempo de evolución.","source":"Banco de preguntas validado"},{"id":"adenopatias-058","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Qué exposiciones deben investigarse ante adenopatías persistentes?","respuesta":"Contacto con tuberculosis o animales, consumo de alimentos no pasteurizados, vacunaciones recientes y medicamentos.","source":"Banco de preguntas validado"},{"id":"adenopatias-059","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Qué foco local debe buscarse activamente durante la historia clínica?","respuesta":"Problemas dentales.","source":"Banco de preguntas validado"},{"id":"adenopatias-060","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Qué características del ganglio deben describirse en el examen físico?","respuesta":"Localización, número, tamaño, movilidad, consistencia, dolor y piel suprayacente.","source":"Banco de preguntas validado"},{"id":"adenopatias-061","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"¿Qué estudio de imagen es útil para valorar la presencia de absceso ganglionar?","respuesta":"Ecografía ganglionar.","source":"Banco de preguntas validado"},{"id":"adenopatias-062","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Qué estudio de imagen puede aportar información ante sospecha de compromiso mediastínico o infección crónica?","respuesta":"Radiografía de tórax.","source":"Banco de preguntas validado"},{"id":"adenopatias-063","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Qué pruebas específicas pueden solicitarse según la sospecha clínica de infección por tuberculosis?","respuesta":"Tuberculina o IGRA.","source":"Banco de preguntas validado"},{"id":"adenopatias-064","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Qué serologías pueden considerarse en el estudio dirigido de adenopatías?","respuesta":"EBV, CMV, VIH y Toxoplasma, según el contexto clínico.","source":"Banco de preguntas validado"},{"id":"adenopatias-065","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Cuándo corresponde cultivar secreción o pus?","respuesta":"Cuando exista secreción o material purulento que pueda orientar el tratamiento.","source":"Banco de preguntas validado"},{"id":"adenopatias-066","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un niño con adenopatía claramente reactiva a una infección viral alta, pequeño, móvil y en mejoría, solicita un panel amplio de estudios. ¿Cuál es la estrategia más adecuada?","respuesta":"Evitar pruebas innecesarias y realizar observación clínica.","source":"Banco de preguntas validado"},{"id":"adenopatias-067","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un niño presenta adenitis unilateral febril con zona fluctuante. ¿Qué estudio debe priorizarse y con qué objetivo?","respuesta":"Ecografía ganglionar para valorar absceso y orientar el drenaje.","source":"Banco de preguntas validado"},{"id":"adenopatias-068","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un paciente presenta adenopatía persistente, dura y fija, sin causa evidente. ¿Qué procedimientos invasivos pueden estar indicados según la evaluación?","respuesta":"PAAF o biopsia escisional. Tratamiento según etiología","source":"Banco de preguntas validado"},{"id":"adenopatias-069","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál es el manejo habitual de una adenopatía viral o reactiva?","respuesta":"Observación y tratamiento sintomático.","source":"Banco de preguntas validado"},{"id":"adenopatias-070","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Contra qué dos patógenos debe dirigirse inicialmente el tratamiento de una adenitis bacteriana aguda?","respuesta":"Staphylococcus aureus y Streptococcus pyogenes.","source":"Banco de preguntas validado"},{"id":"adenopatias-071","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál es la primera opción ambulatoria indicada en la presentación para adenitis bacteriana aguda?","respuesta":"Cefadroxilo.","source":"Banco de preguntas validado"},{"id":"adenopatias-072","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Mencione una alternativa al cefadroxilo para el tratamiento de adenitis bacteriana aguda.","respuesta":"Cloxacilina o clindamicina.","source":"Banco de preguntas validado"},{"id":"adenopatias-073","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"¿Cuál es el tratamiento de elección de las adenopatías por micobacterias no tuberculosas?","respuesta":"Exéresis completa.","source":"Banco de preguntas validado"},{"id":"adenopatias-074","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Por qué se evita el drenaje o la exéresis incompleta en micobacterias no tuberculosas?","respuesta":"Porque puede favorecer la fistulización.","source":"Banco de preguntas validado"},{"id":"adenopatias-075","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Qué esquema inicial se describe para la tuberculosis ganglionar mientras se conoce la sensibilidad?","respuesta":"Isoniacida, etambutol, rifampicina y pirazinamida.","source":"Banco de preguntas validado"},{"id":"adenopatias-076","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Tras conocer la sensibilidad en tuberculosis ganglionar, ¿qué fármacos continúan en el esquema descrito?","respuesta":"Isoniacida y rifampicina.","source":"Banco de preguntas validado"},{"id":"adenopatias-077","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Un niño con adenopatía reactiva viral y buen estado general recibe antibiótico empírico. ¿Qué aspecto del enfoque debe reconsiderarse?","respuesta":"Los antibióticos no están indicados de rutina en adenopatías virales/reactivas; corresponde observación y tratamiento sintomático.","source":"Banco de preguntas validado"},{"id":"adenopatias-078","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un paciente con adenitis bacteriana recibe cefadroxilo. ¿Qué elementos deben guiar el ajuste del tratamiento?","respuesta":"Los resultados de cultivo y la evolución clínica.","source":"Banco de preguntas validado"},{"id":"adenopatias-079","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un niño con adenopatía crónica por micobacterias no tuberculosas tiene piel violácea pero no absceso bacteriano agudo. ¿Qué procedimiento debe evitarse como manejo aislado?","respuesta":"El drenaje simple, porque favorece la fistulización.","source":"Banco de preguntas validado"},{"id":"adenopatias-080","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un niño con fluctuación cervical, fiebre y eritema persiste sintomático. ¿Por qué el antibiótico solo puede ser insuficiente?","respuesta":"Porque un absceso requiere valoración ecográfica, cultivo y posible incisión y drenaje. Referencia, ingreso y esquema práctico","source":"Banco de preguntas validado"},{"id":"adenopatias-081","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Qué edad requiere especial cautela ante síndrome adenitis-celulitis con fiebre elevada?","respuesta":"Menor de 3 meses.","source":"Banco de preguntas validado"},{"id":"adenopatias-082","tema":"adenopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Qué intervalo sin mejoría tras tratamiento empírico obliga a reconsiderar la conducta?","respuesta":"48-72 horas.","source":"Banco de preguntas validado"},{"id":"adenopatias-083","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Qué enfermedades inflamatorias deben considerarse ante adenopatía con fiebre prolongada y hallazgos sistémicos compatibles?","respuesta":"Enfermedad de Kawasaki o síndrome inflamatorio multisistémico.","source":"Banco de preguntas validado"},{"id":"adenopatias-084","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Qué conducta corresponde ante adenopatía progresiva o diagnóstico incierto?","respuesta":"Derivación por sospecha tumoral o necesidad de estudio especializado.","source":"Banco de preguntas validado"},{"id":"adenopatias-085","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Un niño con adenitis bacteriana no mejora tras 72 horas de tratamiento empírico. ¿Qué decisión es apropiada?","respuesta":"Reevaluar, considerar derivación y buscar complicaciones como absceso.","source":"Banco de preguntas validado"},{"id":"adenopatias-086","tema":"adenopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Un escolar presenta fiebre prolongada, adenopatía cervical, conjuntivitis, exantema y cambios mucosos. ¿Qué diagnóstico debe considerarse?","respuesta":"Enfermedad de Kawasaki.","source":"Banco de preguntas validado"},{"id":"adenopatias-087","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un lactante presenta adenopatía unilateral dolorosa, caliente, eritematosa y febril. ¿Cuál es el algoritmo clínico inicial?","respuesta":"Considerar etiología bacteriana, iniciar antibiótico dirigido y añadir ecografía o drenaje si se sospecha absceso.","source":"Banco de preguntas validado"},{"id":"adenopatias-088","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un niño tiene adenopatías bilaterales pequeñas, móviles y síntomas respiratorios altos. ¿Cuál es el algoritmo clínico inicial?","respuesta":"Probable etiología viral/reactiva: observación y tratamiento sintomático.","source":"Banco de preguntas validado"},{"id":"adenopatias-089","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un preescolar presenta adenopatía crónica unilateral indolora con piel violácea. ¿Qué posibilidad debe priorizarse y qué manejo orientativo corresponde?","respuesta":"Micobacterias no tuberculosas; considerar exéresis completa tras la evaluación pertinente.","source":"Banco de preguntas validado"},{"id":"adenopatias-090","tema":"adenopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un paciente presenta adenopatías generalizadas, sin foco infeccioso claro y con estado general deteriorado. ¿Cuál es el enfoque correcto?","respuesta":"Pensar en enfermedad sistémica, ampliar el estudio y derivar según los hallazgos.","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-001","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿En qué semana de gestación comienza la diferenciación del intestino anterior en una porción respiratoria ventral y una porción esofágica dorsal?","respuesta":"4ta semana","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-002","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿En qué semana de gestación se completa normalmente la separación entre la tráquea y el esófago?","respuesta":"6-7 semanas","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-003","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"La atresia esofágica con fístula traqueoesofágica se origina principalmente por:","respuesta":"Un desequilibrio en el crecimiento de los pliegues traqueoesofágicos","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-004","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"El esófago y la tráquea derivan embriológicamente de:","respuesta":"El intestino anterior (foregut)","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-005","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Respecto a la comprensión actual de la embriología de la AE/FTE, es correcto afirmar que:","respuesta":"Continúan las investigaciones genéticas para dilucidar mejor el mecanismo embriológico","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-006","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Un residente pregunta por qué la AE/FTE se asocia frecuentemente con anomalías traqueales como la traqueomalacia. La explicación embriológica más aceptada es que:","respuesta":"El defecto en la separación de los pliegues traqueoesofágicos también altera el desarrollo cartilaginoso de la pared traqueal posterior","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-007","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Cuál de las siguientes afirmaciones sobre la embriogénesis de la AE/FTE es correcta?","respuesta":"El desequilibrio en el crecimiento de los pliegues laterales lleva a comunicación anómala persistente entre ambos tubos","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-008","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"La ventana embriológica crítica en la que un insulto (p. ej. ciertos fármacos) podría alterar la separación traqueoesofágica normal corresponde aproximadamente a:","respuesta":"Semanas 4-7 de gestación","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-009","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Respecto al estado actual del conocimiento embriológico de la AE/FTE, es correcto afirmar que:","respuesta":"Aunque el mecanismo mecánico del pliegue está descrito, persisten investigaciones genéticas activas para precisar la etiología","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-010","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un grupo de investigación estudia modelos animales con mutaciones que alteran genes implicados en la señalización del intestino anterior (foregut), buscando reproducir el fenotipo de AE/FTE. Este enfoque se fundamenta en que:","respuesta":"Aunque el mecanismo descrito es un desequilibrio en el crecimiento de los pliegues, la investigación genética continúa buscando vías moleculares subyacentes","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-011","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Desde el punto de vista embriológico, ¿por qué la mayoría de los pacientes con AE con fístula distal presentan también cierto grado de dismotilidad esofágica intrínseca, independientemente de la técnica quirúrgica empleada?","respuesta":"Porque el desarrollo anómalo de la inervación intrínseca del esófago (plexo mientérico) ocurre como parte del mismo proceso embriológico alterado","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-012","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"La coexistencia frecuente de traqueomalacia, dismotilidad esofágica y anomalías cardíacas/vertebrales en pacientes con AE sindrómica apoya más la hipótesis de que la AE/FTE representa:","respuesta":"Parte de un espectro de disrupción del desarrollo mesodérmico/endodérmico temprano que afecta múltiples estructuras derivadas de regiones embrionarias vecinas Epidemiología y Anomalías Asociadas","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-013","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"La incidencia aproximada de AE/FTE al nacimiento es de:","respuesta":"1 en 2,500-3,000 nacidos vivos","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-014","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"En cuanto a la distribución por sexo de la AE/FTE, existe:","respuesta":"Ligera preponderancia masculina","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-015","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"El riesgo de que un segundo hijo de padres con un niño afectado por AE/FTE también la padezca es aproximadamente:","respuesta":"0.5-2%","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-016","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Qué porcentaje aproximado de pacientes con AE/FTE presenta anomalías cromosómicas?","respuesta":"6-10%","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-017","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál de los siguientes NO se ha descrito como factor ambiental asociado a AE/FTE?","respuesta":"Deficiencia materna de yodo","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-018","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Respecto a la relación entre AE aislada y AE sindrómica, es correcto afirmar que:","respuesta":"Ambas formas se presentan con una frecuencia aproximadamente similar","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-019","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"De las siguientes anomalías asociadas a la AE sindrómica, ¿cuál es la MÁS frecuentemente reportada?","respuesta":"Anomalías cardíacas (13-34%)","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-020","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Un recién nacido con AE presenta además ano imperforado, agenesia renal unilateral y hemivértebras torácicas. Esta combinación es más compatible con:","respuesta":"Asociación VACTERL","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-021","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"En un neonato con AE se documenta coloboma ocular y atresia de coanas. Esta asociación orienta hacia el diagnóstico de:","respuesta":"Síndrome de CHARGE","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-022","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Cuál de los siguientes NO forma parte del acrónimo VACTERL?","respuesta":"Coloboma ocular","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-023","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Una pareja tiene un primer hijo con AE/FTE aislada. Durante la consejería genética preconcepcional para un segundo embarazo, ¿qué información es más precisa para transmitir sobre el riesgo de recurrencia?","respuesta":"El riesgo de recurrencia es aproximadamente 0.5-2%, pero aumenta hasta cerca del 20% si ya existiera más de un hijo previamente afectado","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-024","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un neonato con AE/FTE presenta además cardiopatía congénita compleja y anomalías vertebrales múltiples, sin rasgos dismórficos faciales sugestivos de un síndrome específico. El siguiente paso más apropiado en el abordaje diagnóstico integral es:","respuesta":"Interconsulta con genética para descartar asociaciones no aleatorias como VACTERL y estudio cromosómico según indicación clínica","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-025","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En comparación con la AE aislada, los pacientes con AE sindrómica asociada a anomalías cromosómicas (6-10% del total) tienden a tener:","respuesta":"Mayor morbimortalidad global, condicionada en gran medida por las anomalías asociadas (especialmente cardíacas) Clasificación Anatómica","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-026","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál es el subtipo anatómico más frecuente de AE/FTE?","respuesta":"Atresia esofágica con fístula distal","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-027","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"En la atresia esofágica con fístula distal, la porción proximal del esófago típicamente:","respuesta":"Está dilatada y engrosada","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-028","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"La atresia esofágica pura sin fístula traqueoesofágica tiene una incidencia aproximada de:","respuesta":"7%","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-029","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"La fístula en H (tipo H) se caracteriza por:","respuesta":"Presencia de fístula traqueoesofágica sin atresia esofágica asociada","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-030","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"En términos generales, la atresia esofágica pura sin fístula se caracteriza por una distancia entre los cabos que:","respuesta":"Es considerable, lo que suele impedir la anastomosis inmediata","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-031","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"En la atresia esofágica con fístula proximal (sin fístula distal), la fístula generalmente:","respuesta":"Se origina en la tráquea membranosa proximal y termina en la porción proximal del esófago dilatado","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-032","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Un hallazgo intraoperatorio de burbujas de aire al abrir el cabo esofágico proximal durante la reparación de una AE sugiere fuertemente:","respuesta":"Presencia de una fístula proximal no diagnosticada preoperatoriamente","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-033","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Respecto a la AE con fístulas proximal y distal simultáneas, es correcto afirmar que:","respuesta":"Su incidencia descrita es inferior al 1%","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-034","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Un neonato tiene paso normal de sonda orogástrica al estómago, pero desde el nacimiento presenta tos y episodios de cianosis con la alimentación, además de infecciones respiratorias recurrentes. La entidad que mejor explica este cuadro es:","respuesta":"Fístula traqueoesofágica tipo H sin atresia esofágica","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-035","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Durante una toracotomía por AE, el cirujano identifica un cabo proximal muy dilatado que desciende hasta aproximadamente la 3ra vértebra torácica y un cabo distal fino que se origina en la tráquea justo por encima de la carina. No se identifican otras comunicaciones. Este hallazgo es característico de:","respuesta":"Atresia esofágica con fístula distal (el subtipo más común)","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-036","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En un caso raro descrito en la literatura de AE con una obstrucción membranosa casi completa del esófago, en el que una única fístula traqueoesofágica se origina precisamente a nivel de dicha membrana y comunica ambos segmentos esofágicos, la clasificación anatómica más apropiada corresponde a una variante de:","respuesta":"Atresia esofágica con fístulas proximal y distal","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-037","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Si en un caso de AE con fístula distal esta última se encuentra ocluida por tejido inflamatorio o secreciones, el riesgo clínico principal es:","respuesta":"Un diagnóstico erróneo de 'atresia esofágica sin fístula distal', con implicaciones para la planificación de la brecha y el abordaje quirúrgico","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-038","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Respecto a la fístula traqueoesofágica proximal (sin fístula distal), es correcto afirmar que:","respuesta":"No suele encontrarse una fístula visible al final de la bolsa proximal, y por lo general hay una sola fístula, aunque pueden encontrarse dos o tres Diagnóstico Prenatal y Postnatal","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-039","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuáles son los dos signos ecográficos prenatales inespecíficos clásicamente asociados a AE/FTE?","respuesta":"Polihidramnios y burbuja gástrica ausente o pequeña","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-040","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"El signo clínico postnatal clásico que hace sospechar AE es:","respuesta":"Sialorrea (salivación excesiva) con imposibilidad de pasar una sonda al estómago","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-041","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Para evaluar la permeabilidad esofágica ante sospecha de AE, se recomienda pasar:","respuesta":"Un catéter rígido 10 French por nariz o boca","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-042","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"El estudio inicial más útil para confirmar el diagnóstico postnatal de AE tras la imposibilidad de pasar la sonda es:","respuesta":"Radiografía de tórax (con la sonda in situ)","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-043","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"En el diagnóstico prenatal de AE, el llamado 'signo de la bolsa' (pouch sign) se refiere a:","respuesta":"La combinación de un estómago pequeño y una porción cervical del esófago dilatada","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-044","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Respecto a la sensibilidad de la resonancia magnética fetal para el diagnóstico de AE, la literatura describe un rango aproximado de:","respuesta":"60-100%","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-045","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Un neonato nace de un embarazo complicado con polihidramnios. Independientemente de la clínica inicial, la conducta apropiada es:","respuesta":"Pasar una sonda/catéter para evaluar permeabilidad esofágica de forma sistemática","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-046","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Un recién nacido con aplasia radial (parte del espectro VACTERL) debe evaluarse sistemáticamente para descartar AE mediante:","respuesta":"Paso de sonda orogástrica/catéter para verificar permeabilidad esofágica","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-047","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"En un neonato con sospecha de AE, la radiografía de tórax con la sonda enrollada en el cabo esofágico proximal, junto con aire en el estómago e intestino, es más compatible con:","respuesta":"Atresia esofágica con fístula distal","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-048","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un neonato de 39 semanas con antecedente de polihidramnios severo nace con sialorrea abundante y dificultad respiratoria. Se intenta pasar una sonda orogástrica que se enrolla en el tórax a nivel de T2-T3 en la radiografía, sin aire visible en el abdomen. ¿Cuál es el diagnóstico más probable y qué implica la ausencia de aire abdominal?","respuesta":"AE pura sin fístula (o con fístula distal ocluida); la ausencia de aire abdominal es consistente con que no existe comunicación funcional con la vía aérea distal","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-049","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un cirujano pediatra evalúa a un neonato con sospecha prenatal de AE por polihidramnios y burbuja gástrica pequeña. Decide complementar con RM fetal. Sabiendo que la sensibilidad de este estudio varía entre 60-100%, ¿cuál es la interpretación correcta de un resultado en el que SÍ se logra visualizar la porción torácica del esófago?","respuesta":"Este hallazgo hace menos probable una AE, pero dada la variabilidad del estudio y la posible normalidad esofágica en formas tipo H, no descarta por completo toda la patología del espectro","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-050","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En un neonato con sospecha clínica alta de AE (sialorrea, imposibilidad de alimentación), pero en quien el catéter blando de alimentación logra 'pasar' aparentemente sin resistencia hasta una longitud compatible con el estómago, el residente debe considerar que:","respuesta":"Un catéter blando puede enrollarse en el cabo proximal dando una falsa sensación de paso adecuado; se recomienda usar un catéter más rígido (10 Fr) y confirmar con radiografía","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-051","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En la evaluación diagnóstica de un lactante con sospecha de fístula tipo H aislada (sin atresia), ante estudios contrastados convencionales negativos pero alta sospecha clínica persistente (tos con la alimentación, neumonías recurrentes), el siguiente paso diagnóstico más apropiado es:","respuesta":"Realizar broncoscopía y esofagoscopía combinadas, dado que la fístula en H puede ser difícil de visualizar en esofagogramas convencionales por su trayecto corto y oblicuo Manejo Preoperatorio","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-052","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"La sonda utilizada para el drenaje continuo de secreciones del cabo esofágico proximal en un neonato con AE se llama:","respuesta":"Sonda de Replogle","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-053","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"En un recién nacido con AE/FTE que requiere ventilación mecánica antes de la cirugía, se recomienda:","respuesta":"Ventilación suave con presiones bajas para evitar distensión gástrica por la fístula","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-054","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"En general, la reparación quirúrgica de la AE/FTE se considera:","respuesta":"Una intervención que habitualmente NO es urgente, permitiendo tiempo para evaluar anomalías asociadas","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-055","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Antes de la reparación quirúrgica de la AE/FTE, se recomienda realizar de rutina:","respuesta":"Una ecocardiografía para evaluar anomalías cardíacas y la lateralidad del cayado aórtico","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-056","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"En un neonato con AE/FTE e inestabilidad respiratoria grave que requiere ventilación mecánica con presiones elevadas, el riesgo principal derivado de la fístula distal es:","respuesta":"Paso preferente de aire hacia el estómago a través de la fístula, con distensión gástrica progresiva que compromete aún más la ventilación","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-057","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Ante un neonato con AE/FTE extremadamente inestable en quien la distensión gástrica compromete gravemente la ventilación, una opción de manejo urgente descrita es:","respuesta":"Gastrostomía urgente para descomprimir el estómago","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-058","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"La ligadura urgente de la fístula traqueoesofágica (frecuentemente por vía toracoscópica) como maniobra para 'salvar la vida' se reserva para casos en los que:","respuesta":"Pacientes con inestabilidad extrema en quienes la fístula compromete gravemente la ventilación, difiriendo la reparación definitiva 1-6 semanas","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-059","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Antes de la reparación definitiva de la AE, además de la ecocardiografía, se recomienda evaluar sistemáticamente:","respuesta":"Ecografía renal y radiografía de columna vertebral","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-060","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Respecto al papel de la TC y la RM de tórax/cuello en el manejo preoperatorio habitual de la AE/FTE, es correcto afirmar que:","respuesta":"Aportan mejor definición anatómica pero en la práctica añaden poco al manejo quirúrgico habitual","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-061","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un neonato prematuro con AE/FTE y membrana hialina grave requiere ventilación mecánica con presiones progresivamente más altas; se observa distensión abdominal creciente y desaturación progresiva. ¿Cuál es la conducta más apropiada?","respuesta":"Considerar ligadura urgente de la fístula (frecuentemente por vía toracoscópica) o gastrostomía descompresiva urgente, dado que el aire está pasando preferentemente hacia el estómago a través de la fístula","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-062","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En un neonato en quien se realiza ligadura toracoscópica urgente de la fístula traqueoesofágica por inestabilidad respiratoria extrema, la reparación esofágica definitiva (anastomosis) habitualmente se difiere aproximadamente:","respuesta":"Entre 7-14 días, o incluso 2-6 semanas, según la estabilización clínica del paciente","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-063","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un neonato con AE de brecha larga (más de 6 cuerpos vertebrales medidos entre los cabos) es evaluado por un cirujano experimentado. La estrategia terapéutica más probable a considerar en este escenario es:","respuesta":"Reemplazo esofágico, dado que la brecha es demasiado extensa para una anastomosis directa convencional","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-064","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Para un neonato con AE en quien la brecha medida entre cabos es de aproximadamente 3-4 cuerpos vertebrales, la estrategia inicial más razonable, según la experiencia quirúrgica descrita, es:","respuesta":"Anastomosis primaria tardía, permitiendo el crecimiento espontáneo de los cabos antes de la reconstrucción Reparación Quirúrgica","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-065","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Las dos vías principales para el abordaje quirúrgico de la reparación de AE/FTE son:","respuesta":"Toracotomía y toracoscopia","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-066","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"El objetivo quirúrgico principal en la AE con fístula distal es:","respuesta":"Ligar y seccionar la fístula traqueoesofágica y realizar anastomosis esofágica primaria","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-067","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Durante el período postoperatorio inmediato de una anastomosis esofágica con tensión considerable, es habitual mantener al neonato con:","respuesta":"Ventilación mecánica con relajación muscular por algunos días","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-068","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Antes de retirar el drenaje torácico o iniciar la alimentación oral plena tras la reparación, se recomienda:","respuesta":"Un estudio de contraste esofágico para descartar fuga anastomótica","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-069","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"El lado de entrada torácica (derecho vs izquierdo) para la reparación de AE con fístula distal se determina fundamentalmente por:","respuesta":"El lado hacia el que desciende el cayado aórtico, entrando por el lado opuesto","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-070","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"En un neonato con cayado aórtico que desciende hacia la derecha (variante presente en aproximadamente 3% de los casos), el abordaje torácico recomendado para la reparación de la AE es:","respuesta":"Toracotomía izquierda","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-071","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"La broncoscopía rígida preoperatoria en la reparación de AE/FTE es especialmente útil porque permite:","respuesta":"Identificar una fístula proximal adicional, cuya coexistencia con la distal ocurre en menos del 5% de los casos","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-072","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Durante la reparación toracoscópica de la AE con fístula distal, respecto al abordaje abierto tradicional, una ventaja generalmente reconocida es:","respuesta":"Evitar la morbilidad músculoesquelética asociada a la toracotomía abierta","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-073","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Durante la reparación toracoscópica de una AE con fístula distal, el cirujano nota que la anastomosis quedará bajo tensión considerable. ¿Cuál es la conducta postoperatoria más apropiada respecto al soporte ventilatorio?","respuesta":"Mantener ventilación mecánica con relajación muscular durante aproximadamente 5 días para proteger la anastomosis de la tracción","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-074","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En la reparación de AE con fístula distal, la broncoscopía rígida preoperatoria tiene especial relevancia quirúrgica porque:","respuesta":"Permite descartar una fístula proximal asociada, cuya presencia simultánea con la distal, aunque infrecuente (<5%), cambiaría la estrategia quirúrgica al requerir su identificación y ligadura adicional","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-075","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un neonato con situs solitus y cayado aórtico que desciende hacia la derecha (confirmado por ecocardiografía preoperatoria) va a ser llevado a reparación de AE con fístula distal. El cirujano decide abordar por toracotomía izquierda. ¿Es correcta esta decisión y por qué?","respuesta":"Es correcta; el abordaje se realiza por el lado opuesto al de descenso del cayado aórtico, y esta variante (cayado derecho) ocurre en aproximadamente 3% de los casos","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-076","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Comparado con el abordaje toracoscópico, uno de los argumentos históricos a favor de la toracotomía abierta convencional en casos técnicamente muy complejos de AE ha sido:","respuesta":"Que, en manos con menor experiencia toracoscópica o en brechas muy largas, la exposición directa puede facilitar el manejo de una anastomosis técnicamente difícil","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-077","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En un neonato con AE con fístula distal se realiza toracotomía derecha (cayado aórtico izquierdo normal) sin broncoscopía preoperatoria disponible. Durante la cirugía, tras seccionar la fístula distal y antes de completar la anastomosis, el cirujano nota burbujas de aire al abrir el cabo proximal. La conducta más apropiada es:","respuesta":"Sospechar una fístula proximal no diagnosticada e inspeccionar cuidadosamente el cabo proximal antes de completar la reconstrucción Complicaciones y Seguimiento","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-078","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Se define la estenosis anastomótica esofágica postquirúrgica como un estrechamiento de la luz mayor de:","respuesta":"50%","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-079","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál de las siguientes es una complicación tardía reconocida tras la reparación de AE/FTE?","respuesta":"Traqueomalacia","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-080","tema":"atresia_esofagica","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"La morbilidad relacionada con la toracotomía en niños operados de AE/FTE puede incluir a largo plazo:","respuesta":"Escoliosis y asimetría de la pared torácica","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-081","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Un lactante operado de AE hace 3 meses presenta episodios de tos durante la alimentación, cianosis intermitente e infecciones respiratorias recurrentes. Los estudios más apropiados para investigar una posible fístula traqueoesofágica recurrente son:","respuesta":"Esofagograma y broncoscopía","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-082","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Entre los factores de riesgo descritos para el desarrollo de estenosis anastomótica tras la reparación de AE se incluyen todos los siguientes, EXCEPTO:","respuesta":"Bajo peso materno pregestacional","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-083","tema":"atresia_esofagica","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Respecto al tratamiento de la estenosis anastomótica esofágica sintomática tras reparación de AE, la evidencia actual sugiere que:","respuesta":"La dilatación con balón parece más efectiva que otras técnicas cuando se requiere tratamiento","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-084","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un lactante de 2 meses, operado de AE con fístula distal al nacer, es llevado a control con esofagograma que muestra fuga contenida sin repercusión clínica sistémica en el día 5 postoperatorio. ¿Cuál es la conducta más apropiada?","respuesta":"Manejo expectante con drenaje adecuado y soporte nutricional, dado que la mayoría de las fugas anastomóticas cierran espontáneamente","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-085","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un lactante de 4 meses operado de AE presenta episodios repetidos de tos durante las tomas, apnea ocasional y dos neumonías en los últimos dos meses. Se documenta por esofagograma y broncoscopía una comunicación anómala entre esófago y tráquea a nivel de la anastomosis previa. El diagnóstico más probable y su etiología habitual son:","respuesta":"Fístula traqueoesofágica recurrente, habitualmente relacionada con una fuga anastomótica previa","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-086","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"El tratamiento de la fístula traqueoesofágica recurrente es considerado técnicamente difícil; entre las opciones descritas se incluyen todas las siguientes EXCEPTO:","respuesta":"Reemplazo gástrico total profiláctico como primera línea","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-087","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un lactante de 6 meses con antecedente de AE reparada presenta episodios recurrentes de tos y 'sonido de foca' durante la espiración y el llanto, con desaturaciones ocasionales durante la alimentación. La broncoscopía muestra colapso significativo de la pared traqueal posterior en la región donde antes estaba la fístula, durante la espiración. Si los síntomas son graves y persistentes, el tratamiento quirúrgico definitivo más apropiado es:","respuesta":"Aortopexia, para traccionar el cayado aórtico anteriormente y ampliar la luz traqueal colapsada","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-088","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un adolescente con antecedente de AE reparada en el período neonatal refiere disfagia intermitente para sólidos, episodios ocasionales de impactación de cuerpo extraño alimentario y pirosis crónica no bien controlada. Este cuadro clínico a largo plazo se relaciona más probablemente con:","respuesta":"Alteración del peristaltismo esofágico intrínseco y reflujo gastroesofágico crónico, complicaciones reconocidas a largo plazo de la AE reparada","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-089","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Respecto al seguimiento a largo plazo de pacientes con AE reparada y RGE crónico no controlado, es relevante conocer que:","respuesta":"Se ha descrito el riesgo de complicaciones esofágicas a largo plazo, incluido el cáncer de esófago, en relación con el reflujo y la dismotilidad crónicos, lo que justifica seguimiento","source":"Banco de preguntas validado"},{"id":"atresia_esofagica-090","tema":"atresia_esofagica","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Antes de la reparación quirúrgica de la AE, un cirujano decide realizar laringoscopía/broncoscopía para evaluar la movilidad de las cuerdas vocales. La justificación principal de esta práctica recomendada es:","respuesta":"Permite identificar preoperatoriamente una parálisis congénita de cuerdas vocales, entidad descrita hasta en 3% de los niños operados, lo cual influye en el manejo perioperatorio","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-091","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál es la diferencia fundamental entre atresia y estenosis duodenal?","respuesta":"La atresia es obstrucción completa del lumen y la estenosis es obstrucción incompleta","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-092","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál es la incidencia aproximada de la atresia duodenal en recién nacidos vivos?","respuesta":"1 en 5000-10000","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-093","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál es la causa más común de obstrucción duodenal congénita?","respuesta":"Atresia duodenal","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-094","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Con respecto a la clasificación anatómica de la atresia duodenal, ¿cuál tipo representa más del 90% de los casos y se caracteriza por un diafragma luminal compuesto de mucosa y submucosa?","respuesta":"Tipo I","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-095","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Un recién nacido, por lo demás estable, presenta vómitos biliosos dentro de las primeras horas de vida. ¿Cuál es el diagnóstico que se debe sospechar primero?","respuesta":"Obstrucción duodenal congénita (atresia/estenosis)","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-096","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Cuál es el mecanismo embriológico principal que explica la formación de la mayoría de las atresias duodenales?","respuesta":"Pérdida focal de células epiteliales durante el desarrollo, en lugar de una falla en la vacuolización del estado hiperproliferativo","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-097","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Respecto al páncreas anular como causa de obstrucción duodenal, ¿cuál es la comprensión actual de su etiología?","respuesta":"Es resultado principalmente de la falla del desarrollo duodenal normal, más que de una verdadera constricción externa","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-098","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Un neonato presenta emesis NO biliosa en las primeras horas de vida y se documenta atresia duodenal en la cirugía. ¿Qué localización de la obstrucción explica este hallazgo?","respuesta":"Obstrucción pre-ampular (aproximadamente 15% de los casos)","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-099","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Por qué en la atresia duodenal tipo II es especialmente importante la disección cuidadosa durante la cirugía?","respuesta":"Porque el cordón fibroso que conecta los segmentos proximal y distal puede estar cerca de estructuras biliares y debe manejarse con precaución","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-100","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Cuál es el rango reportado de anomalías asociadas en pacientes con atresia duodenal, y cuáles son las más frecuentes?","respuesta":"45-65%, incluyendo trisomía 21, malformaciones cardíacas y malrotación intestinal","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-101","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Recién nacido de término con diagnóstico prenatal de polihidramnios nace con vómitos biliosos desde las primeras horas de vida. La radiografía de abdomen muestra doble burbuja sin gas distal. En la cirugía se encuentra separación completa entre los segmentos duodenales proximal y distal, sin cordón fibroso, asociada a páncreas anular. ¿Qué tipo de atresia duodenal corresponde a este hallazgo?","respuesta":"Tipo III","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-102","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En un neonato con atresia duodenal tipo I (membrana luminal), existe el riesgo de que la membrana se prolapse distalmente formando una deformidad en \"manga de viento\" (windsock). ¿Cuál es la implicación quirúrgica más importante de este hallazgo?","respuesta":"El punto de inserción externo aparente de la membrana puede estar más distal que el sitio real de obstrucción, por lo que debe evaluarse cuidadosamente antes de la duodenotomía","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-103","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un lactante de 3 semanas, producto de embarazo con polihidramnios, presenta vómitos NO biliosos intermitentes y falla de medro progresiva. La radiografía simple no muestra doble burbuja clara. ¿Cuál es el siguiente paso diagnóstico más apropiado?","respuesta":"Estudio de contraste del tracto digestivo superior (tránsito esofagogastroduodenal)","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-104","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"¿Por qué la localización de la obstrucción duodenal en relación con la ampolla de Vater es clínicamente relevante para interpretar el cuadro clínico inicial?","respuesta":"Porque determina si la emesis será biliosa (obstrucción post-ampular, aproximadamente 85%) o no biliosa (obstrucción pre-ampular, aproximadamente 15%)","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-105","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Neonato con trisomía 21 confirmada, cardiopatía congénita y atresia duodenal tipo I. Antes de programar la cirugía correctora duodenal, el equipo solicita ecocardiografía y evaluación cardiológica. ¿Cuál es la justificación clínica principal de esta secuencia?","respuesta":"Optimizar el estado cardiovascular y estratificar el riesgo anestésico-quirúrgico antes de una cirugía electiva/semi- electiva Atresia Yeyunoileal","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-106","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál es el mecanismo etiológico aceptado para la atresia yeyunoileal?","respuesta":"Un insulto isquémico intrauterino sobre un intestino ya formado","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-107","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál es la incidencia aproximada de la atresia/estenosis yeyunoileal, y cómo se distribuye entre sexos?","respuesta":"1 en 5000 nacidos vivos, afecta igual a niños y niñas","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-108","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Respecto a la atresia tipo I yeyunoileal, ¿cuál de las siguientes afirmaciones es correcta?","respuesta":"Hay una membrana de mucosa y submucosa con muscularis y serosa intactas, sin acortamiento intestinal","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-109","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"La atresia yeyunoileal tipo IIIB se conoce clásicamente por su aspecto característico. ¿Cómo se le denomina?","respuesta":"Cáscara de manzana o árbol de Navidad","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-110","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál es el hallazgo característico que distingue a la atresia yeyunoileal tipo IV?","respuesta":"Presencia de múltiples segmentos atrésicos o una combinación de los tipos I a III","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-111","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Qué otros insultos vasculares intrauterinos pueden dar origen a una atresia yeyunoileal, además de un evento isquémico primario?","respuesta":"Invaginación intestinal, vólvulo, oclusión tromboembólica y hernias internas transmesentéricas","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-112","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Un neonato con atresia yeyunal tipo IIIA presenta, en el intraoperatorio, un extremo proximal ciego y dilatado sin cordón fibroso, con un defecto mesentérico en forma de V. ¿Qué característica de la longitud intestinal es esperable?","respuesta":"Longitud intestinal total variable, usualmente menor a la normal por reabsorción intrauterina del segmento afectado","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-113","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Cuál es la base fisiopatológica de la falta de peristalsis efectiva en el segmento proximal dilatado de una atresia yeyunoileal?","respuesta":"Vellosidades histológicamente normales pero con deficiencia de enzimas mucosas y ATPasa muscular, además de ganglios entéricos atróficos en el sitio de la atresia","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-114","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Por qué debe reconocerse y tratarse con urgencia la obstrucción intestinal neonatal ante la sospecha de atresia yeyunoileal?","respuesta":"Por la posibilidad concomitante de un vólvulo de intestino medio o una hernia interna con isquemia subsecuente","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-115","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"En un recién nacido con atresia yeyunoileal, ¿qué hallazgo en las deposiciones es más frecuente encontrar, en contraste con la creencia de que el meconio no puede pasar?","respuesta":"Un tapón mucoso grisáceo, ya que el meconio puede ser normal","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-116","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En la laparotomía de un neonato con atresia yeyunal proximal se observa ausencia de la arteria mesentérica superior más allá del origen de la rama cólica media, agenesia del mesenterio dorsal y el intestino distal enrollado en forma helicoidal alrededor de un único vaso proveniente de la arcada ileocólica. ¿Qué tipo de atresia yeyunoileal es esta?","respuesta":"Tipo IIIB (\"cáscara de manzana\")","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-117","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En el manejo de la atresia tipo IIIB (\"cáscara de manzana\"), ¿cuál es la mayor preocupación quirúrgica en relación con la longitud intestinal remanente?","respuesta":"La pérdida significativa de longitud intestinal predispone al síndrome de intestino corto, por lo que debe preservarse la mayor longitud viable posible","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-118","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Neonato de 24 horas de vida con distensión abdominal progresiva, vómito bilioso y ausencia de paso de meconio. En la exploración quirúrgica se identifican tres segmentos atrésicos separados a lo largo del intestino delgado. Además, se documenta hipogammaglobulinemia severa en los estudios complementarios. ¿Qué tipo de atresia yeyunoileal es más consistente con este cuadro?","respuesta":"Tipo IV","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-119","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"¿Cuál es la razón fisiopatológica por la que se recomienda resecar el bulbo proximal dilatado además del extremo proximal del intestino atrésico distal en la cirugía de atresia yeyunoileal?","respuesta":"Porque el segmento proximal dilatado tiene un defecto funcional de peristalsis por deficiencia enzimática y ganglios entéricos atróficos, lo que perpetuaría la disfunción motora si no se reseca","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-120","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Recién nacido pretérmino de 32 semanas con gastrosquisis y atresia intestinal múltiple asociada. Tras la reducción del defecto de pared abdominal y resección de los segmentos afectados, quedan aproximadamente 50 cm de intestino delgado con válvula ileocecal preservada. ¿Cuál de los siguientes factores mejora más el pronóstico de adaptación intestinal en este caso?","respuesta":"La presencia de la válvula ileocecal, que permite una adaptación intestinal más rápida cuando la longitud del intestino delgado es corta Atresia de Colon","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-121","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Qué tan frecuente es la atresia de colon en comparación con otras atresias del tubo digestivo?","respuesta":"Es rara, representando solo el 2-15% de todas las atresias gastrointestinales","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-122","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál es la etiología propuesta para la atresia de colon?","respuesta":"Un insulto vascular (isquémico) sobre el colon ya formado","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-123","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuáles son las manifestaciones clínicas clásicas de la atresia de colon en el neonato?","respuesta":"Distensión abdominal, vómito biliar y falla en el paso de meconio","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-124","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"En la clasificación de la atresia de colon, ¿qué caracteriza al tipo II?","respuesta":"Extremos atrésicos separados por un cordón fibroso","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-125","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál es la incidencia aproximada de la atresia de colon en nacidos vivos?","respuesta":"1 en 20000","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-126","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Con qué otras anomalías congénitas se asocia con mayor frecuencia la atresia de colon?","respuesta":"Gastrosquisis, enfermedad de Hirschsprung, anomalías urológicas y mesenterio no fijado","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-127","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Cómo se compara la tasa de anomalías asociadas de la atresia de colon con la de otras atresias intestinales (duodenal y yeyunoileal)?","respuesta":"Es mucho menor en comparación","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-128","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"En la radiografía simple de abdomen de un neonato con atresia de colon, ¿qué hallazgo característico puede observarse además de niveles hidroaéreos y dilatación de asas del intestino grueso?","respuesta":"Apariencia de vidrio esmerilado","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-129","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Por qué la atresia de colon representa una urgencia quirúrgica más apremiante que la atresia yeyunoileal?","respuesta":"Porque el riesgo de perforación es más alto que el observado en las atresias yeyunoileales","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-130","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Cuál es el mecanismo fisiopatológico que explica la alta mortalidad cuando el diagnóstico de atresia de colon se retrasa más de 72 horas?","respuesta":"Obstrucción de asa ciega entre la válvula ileocecal y la atresia, con distensión masiva del colon y perforación","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-131","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Neonato de 4 días de vida (diagnóstico realizado tardíamente) con distensión abdominal masiva, vómito bilioso y ausencia de meconio. El enema con contraste muestra un colon distal de pequeño calibre que se detiene abruptamente. Durante la cirugía se encuentra perforación cecal con datos de sepsis. ¿Qué mecanismo fisiopatológico explica mejor esta complicación por el retraso diagnóstico?","respuesta":"Obstrucción de asa ciega entre la válvula ileocecal y la atresia, generando distensión masiva del colon proximal (incluyendo el ciego) y perforación","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-132","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"¿Por qué el manejo de la atresia de colon habitualmente se realiza en etapas (colostomía inicial) en lugar de anastomosis primaria inmediata en todos los casos?","respuesta":"Por el mayor riesgo de perforación, la frecuente distensión importante del colon proximal y la posibilidad de compromiso de la vascularidad del segmento dilatado","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-133","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En un recién nacido con atresia de colon diagnosticada tempranamente (menos de 24 horas de vida), sin comorbilidades asociadas, se realiza colostomía con fístula mucosa como primer tiempo quirúrgico. ¿Cuál es la mortalidad esperada aproximada en este escenario favorable?","respuesta":"Menor al 10%","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-134","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"¿Cuál hallazgo intraoperatorio adicional debe buscarse activamente en un paciente con atresia de colon, dada su asociación descrita, y que podría modificar el plan quirúrgico?","respuesta":"Enfermedad de Hirschsprung concomitante, mediante biopsias del colon distal antes de definir el sitio de anastomosis o estoma","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-135","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Neonato con gastrosquisis reducida quirúrgicamente que en su evolución desarrolla distensión abdominal y ausencia de tránsito a nivel de un segmento colónico específico, documentándose atresia de colon tipo III asociada. ¿Qué característica anatómica define a este tipo?","respuesta":"Segmentos atrésicos separados por un defecto mesentérico en forma de V Diagnóstico y Estudios de Imagen","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-136","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál es el signo radiológico clásico de la atresia duodenal completa en una radiografía de abdomen en posición vertical?","respuesta":"Signo de la doble burbuja sin gas distal","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-137","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"En la evaluación de un recién nacido con sospecha de obstrucción intestinal alta, ¿qué volumen de aspirado gástrico por sonda nasogástrica se considera sugestivo de obstrucción?","respuesta":"Más de 20 mL","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-138","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Qué hallazgo ecográfico prenatal se asocia clásicamente con la atresia duodenal?","respuesta":"Polihidramnios con dos estructuras líquidas (doble burbuja) en el abdomen fetal","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-139","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál estudio confirma el diagnóstico de atresia de colon al mostrar un colon distal de pequeño calibre que se detiene abruptamente en el sitio de la atresia?","respuesta":"Enema con contraste","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-140","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cómo se realiza habitualmente el diagnóstico de una estenosis duodenal, ya que el signo de la doble burbuja frecuentemente está ausente?","respuesta":"Mediante un estudio de contraste del tracto digestivo superior (tránsito esofagogastroduodenal)","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-141","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"En un recién nacido con atresia duodenal, ¿en qué situación puede observarse gas distal en la radiografía a pesar de existir una obstrucción completa?","respuesta":"Cuando existe un conducto biliar bífido con inserción anterior y posterior a la atresia","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-142","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Cuál es el fundamento fisiológico del uso del aire deglutido como medio de contraste natural en la radiografía simple de abdomen de un neonato con sospecha de atresia intestinal?","respuesta":"El aire deglutido alcanza el intestino proximal en aproximadamente 1 hora y el intestino distal en aproximadamente 3 horas en un recién nacido vigoroso","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-143","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Por qué puede ser radiológicamente difícil diferenciar una atresia ileal distal de una atresia colónica en un recién nacido mediante radiografía simple?","respuesta":"Porque las marcas de las austras rara vez son visibles en un recién nacido","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-144","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Ante un neonato con sospecha de obstrucción intestinal baja, ¿cuáles estudios especiales ayudan a diferenciar íleo meconial, fibrosis quística y aganglionosis colónica total del diagnóstico de atresia intestinal?","respuesta":"Tránsito digestivo superior, enema contrastado, biopsia rectal y test del sudor","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-145","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Una ecografía prenatal muestra polihidramnios y dos estructuras quísticas contiguas en el abdomen fetal detectadas hacia el tercer trimestre. ¿Cuál es la interpretación más probable de este hallazgo?","respuesta":"Atresia o estenosis duodenal con signo de doble burbuja prenatal","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-146","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Ecografía obstétrica de las 30 semanas reporta polihidramnios y dos imágenes quísticas abdominales fetales comunicadas entre sí. Al nacer, el neonato presenta vómito bilioso y la radiografía simple confirma doble burbuja sin gas distal. ¿Qué información adicional NO puede obtenerse de la radiografía simple y requeriría un estudio contrastado si se sospechara estenosis en lugar de atresia completa?","respuesta":"El grado de obstrucción (completa vs. incompleta) cuando el signo de doble burbuja no es concluyente","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-147","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un recién nacido con sospecha de obstrucción intestinal distal presenta radiografía con múltiples asas dilatadas de intestino delgado y grueso sin distinción clara entre íleon distal dilatado y colon, dado que las austras rara vez se visualizan en el neonato. ¿Cuál es el estudio de elección para diferenciar entre atresia ileal distal y atresia colónica, y por qué?","respuesta":"Enema con contraste, porque delinea el calibre y la anatomía del colon distal (microcolon) y localiza el punto de detención abrupta","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-148","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En un neonato con obstrucción intestinal baja, el diagnóstico diferencial incluye íleo meconial, enfermedad de Hirschsprung y atresia intestinal. ¿Qué combinación de estudios permite diferenciar mejor estas tres entidades?","respuesta":"Tránsito digestivo superior, enema contrastado, biopsia rectal y test del sudor, correlacionados con la clínica","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-149","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"¿Qué limitación tiene el uso del aire deglutido como contraste natural en la radiografía simple de un recién nacido prematuro o enfermo con succión débil, y cómo puede afectar la interpretación del estudio?","respuesta":"El tránsito del aire deglutido está retrasado en estos neonatos, lo que puede simular un patrón obstructivo más proximal del que realmente existe","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-150","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un lactante de 4 meses con antecedente de vómitos intermitentes desde el nacimiento, que nunca fueron estudiados a fondo, es evaluado ahora por falla de medro. El estudio contrastado revela una zona de estrechamiento localizado del intestino delgado sin disrupción de la pared ni defecto mesentérico. ¿Qué entidad es más consistente con este hallazgo tardío?","respuesta":"Estenosis yeyunoileal, cuyo diagnóstico puede retrasarse por años debido a que la clínica depende del nivel y grado de estrechamiento Manejo Quirúrgico","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-151","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál es la técnica quirúrgica estándar para la corrección de la atresia duodenal?","respuesta":"Duodenoduodenostomía en forma de diamante","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-152","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Antes de llevar a un neonato con obstrucción duodenal al quirófano, ¿cuáles son las medidas preoperatorias esenciales?","respuesta":"Descompresión gástrica y corrección del desequilibrio hidroelectrolítico","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-153","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál es el manejo quirúrgico general recomendado para la atresia yeyunoileal tipo I y II?","respuesta":"Resección del intestino proximal dilatado con anastomosis término-terminal","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-154","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"En el manejo quirúrgico de la atresia de colon, ¿cuál es el primer paso del abordaje en etapas recomendado?","respuesta":"Colostomía con fístula mucosa","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-155","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Si durante la laparotomía por atresia intestinal se identifica malrotación asociada, ¿qué procedimiento adicional debe realizarse?","respuesta":"Procedimiento de Ladd","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-156","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Antes de la cirugía correctora de una atresia duodenal, ¿qué estudios complementarios se recomiendan para descartar anomalías asociadas?","respuesta":"Perfil metabólico completo, conteo sanguíneo, estudios de coagulación, ecografía abdominal y espinal, y ecocardiografía","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-157","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Por qué técnicas como la enteroplastia transversa, la excisión aislada de la membrana o los procedimientos de bypass NO son recomendadas para el manejo de la atresia o estenosis yeyunoileal?","respuesta":"Porque fallan en remover el segmento anormal y pueden producir síndrome de asa ciega","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-158","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Durante la resección del intestino proximal dilatado e hipertrófico en la cirugía de atresia yeyunoileal, ¿cuánto intestino distal adicional se recomienda resecar habitualmente y con qué técnica de anastomosis?","respuesta":"Se resecan 4-5 cm del intestino distal y se realiza anastomosis término-terminal","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-159","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Cuál es el objetivo primordial durante la exploración quirúrgica de un neonato con atresia intestinal múltiple, más allá de restaurar la continuidad intestinal?","respuesta":"Preservar la adecuada función y longitud intestinal mediante una inspección cuidadosa de todo el intestino","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-160","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Cuáles son los tres abordajes quirúrgicos descritos para el manejo de la atresia yeyunoileal según la fuente de referencia?","respuesta":"Laparoscópico con anastomosis extracorpórea, incisión transumbilical e incisión transversa supra o infraumbilical","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-161","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Durante la corrección de una atresia duodenal, el cirujano opta por una duodenoduodenostomía en forma de diamante (técnica de Kimura) en lugar de una anastomosis latero-lateral simple. ¿Cuál es la principal ventaja de esta técnica?","respuesta":"Crea una anastomosis más amplia y funcional que reduce el riesgo de obstrucción funcional por discrepancia de calibre entre los segmentos proximal dilatado y distal colapsado","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-162","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En un neonato con atresia yeyunoileal y marcada discrepancia de calibre entre el segmento proximal dilatado y el distal colapsado, ¿qué maniobra adicional a la resección puede considerarse para mejorar la función postoperatoria de la anastomosis?","respuesta":"Reducción (tapering) del intestino proximal dilatado","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-163","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En la laparotomía de un neonato con atresia yeyunal se decide realizar el abordaje mediante incisión transumbilical con resección y anastomosis extracorpórea asistida por laparoscopia. ¿Cuál es la justificación principal de este abordaje mínimamente invasivo asistido?","respuesta":"Permitir la inspección y el manejo del intestino con menor trauma de la pared abdominal, manteniendo los mismos principios de resección y anastomosis que la cirugía abierta","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-164","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"¿Por qué, al planear la anastomosis en un paciente con múltiples atresias intestinales (tipo IV), es fundamental la inspección meticulosa de todo el intestino antes de decidir la estrategia quirúrgica definitiva?","respuesta":"Porque pasar por alto un segmento atrésico adicional podría dejar una obstrucción residual, y porque la estrategia debe equilibrar restaurar la continuidad con preservar la mayor longitud funcional posible","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-165","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Neonato con atresia yeyunal tipo II y malrotación intestinal concomitante identificada en la cirugía. ¿Cuál es la secuencia de manejo intraoperatorio más apropiada?","respuesta":"Realizar el procedimiento de Ladd para corregir la malrotación y luego proceder con la resección y anastomosis de la atresia Cuidados Postoperatorios y Pronóstico","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-166","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Qué papel cumple la nutrición parenteral total (NPT) en el manejo postoperatorio de estos neonatos?","respuesta":"Se utiliza tan pronto como sea posible y se continúa hasta que el infante tolere completamente la vía oral","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-167","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál es la sobrevida a largo plazo aproximada reportada después de la corrección quirúrgica de la atresia duodenal?","respuesta":"Aproximadamente 90%","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-168","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuáles son dos requisitos clínicos básicos que debe cumplir un neonato antes de iniciar la vía oral tras la cirugía?","respuesta":"Aspirado gástrico claro con gasto mínimo y que esté defecando","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-169","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál de los siguientes factores se asocia con el PEOR pronóstico en recién nacidos con atresia yeyunoileal?","respuesta":"Presencia de anomalías congénitas graves asociadas o síndrome de intestino corto","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-170","tema":"atresia_intestinal","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"En la atresia de colon, ¿cómo cambia la mortalidad cuando el diagnóstico y tratamiento se retrasan más de 72 horas?","respuesta":"La mortalidad aumenta a más del 60%","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-171","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Cuál es la longitud aproximada normal del intestino delgado en un recién nacido de término, y cómo se compara con la de un prematuro?","respuesta":"Aproximadamente 250 cm en el de término, y de 160-240 cm en el pretérmino","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-172","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Cuáles son las principales complicaciones a largo plazo descritas tras la corrección de la atresia duodenal?","respuesta":"Vaciamiento gástrico retardado, RGE severo, megaduodeno y síndrome de asa ciega","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-173","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Cómo se debe iniciar y avanzar la alimentación enteral por sonda en el postoperatorio de un neonato operado de atresia intestinal, una vez cumplidos los criterios clínicos?","respuesta":"Iniciar a 20 mL/kg/día de forma continua e incrementar de 20-30 mL/kg/día","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-174","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Qué disfunción gastrointestinal transitoria debe anticiparse en neonatos con reparo de atresia tipo IIIB o síndrome de intestino corto?","respuesta":"Intolerancia a la lactosa, malabsorción por estasis con sobrecrecimiento bacteriano y diarrea","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-175","tema":"atresia_intestinal","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Qué fármacos se mencionan como parte del manejo complementario del síndrome de intestino corto o la disfunción intestinal postoperatoria en estos pacientes?","respuesta":"Loperamida, colestiramina, vitamina B12 y ácido fólico","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-176","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Lactante de 2 meses, operado al nacer por atresia yeyunal tipo IIIB con resección extensa, quedando aproximadamente 40 cm de intestino delgado sin válvula ileocecal. Presenta diarrea crónica, distensión y datos de malabsorción con sobrecrecimiento bacteriano documentado. ¿Cuál es el manejo farmacológico complementario más apropiado en este contexto, según lo descrito para el síndrome de intestino corto?","respuesta":"Loperamida y colestiramina, junto con suplementación de vitamina B12 y ácido fólico","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-177","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"¿Por qué la ausencia de la válvula ileocecal empeora el pronóstico funcional en un paciente con intestino delgado residual corto, en comparación con un paciente de longitud similar pero con la válvula preservada?","respuesta":"La válvula ileocecal contribuye a una adaptación intestinal más rápida y ayuda a prevenir el sobrecrecimiento bacteriano al retrasar el tránsito y funcionar como barrera relativa entre intestino delgado y colon","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-178","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un neonato postoperado de atresia duodenal presenta, a las 3 semanas, vómitos persistentes no biliosos, distensión epigástrica y una radiografía que muestra dilatación marcada del duodeno proximal a la anastomosis sin evidencia de obstrucción mecánica en el estudio contrastado. ¿Cuál complicación a largo plazo descrita es más consistente con este cuadro?","respuesta":"Megaduodeno con vaciamiento gástrico retardado","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-179","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En términos de adaptación intestinal funcional a largo plazo, ¿por qué una atresia que compromete predominantemente el íleon tiene, en igualdad de longitud remanente, mejor pronóstico funcional que una que compromete predominantemente el yeyuno?","respuesta":"Porque el íleon se adapta mejor que el yeyuno tras la pérdida de longitud intestinal, siendo la localización uno de los principales factores pronósticos funcionales","source":"Banco de preguntas validado"},{"id":"atresia_intestinal-180","tema":"atresia_intestinal","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Neonato pretérmino de 34 semanas con atresia yeyunoileal múltiple (tipo IV), a quien se le resecan varios segmentos, quedando un intestino delgado funcional corto. Durante el seguimiento a los 6 meses, la familia pregunta sobre el pronóstico funcional del niño. ¿Qué conjunto de factores debe explicarse a la familia como determinantes principales del pronóstico?","respuesta":"La localización de la atresia, la madurez intestinal, la longitud del intestino delgado remanente y la presencia o ausencia de la válvula ileocecal","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-181","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿En qué etapa del desarrollo pulmonar embrionario se forma y desarrolla el sistema de conductos broncopulmonares, sin que aún sea posible la respiración?","respuesta":"Periodo pseudoglandular","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-182","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Durante el período canalicular del desarrollo pulmonar (aproximadamente semana 17 a 26), ¿cuál es el evento fisiológico más relevante?","respuesta":"Se completa la capilarización y se forman los bronquiolos terminales","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-183","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿En qué etapa del desarrollo pulmonar se diferencian los neumocitos tipo I y se completa la formación de los sacos terminales, sentando las bases para la viabilidad extrauterina?","respuesta":"Sacular","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-184","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Al momento del nacimiento, ¿aproximadamente cuántos alvéolos tiene el pulmón humano, en comparación con la cifra que alcanzará en la edad adulta?","respuesta":"20-25 millones al nacer, hasta 300 millones en el adulto","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-185","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"El espacio muerto anatómico corresponde a las vías aéreas de conducción que no participan en el intercambio gaseoso. ¿Qué generaciones bronquiales lo conforman?","respuesta":"Generaciones 1 a 16","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-186","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"El espacio muerto fisiológico total se calcula como la suma del espacio muerto anatómico más el espacio muerto alveolar. ¿En qué situación clínica aumenta principalmente el componente alveolar de este espacio muerto?","respuesta":"Cuando existen alvéolos ventilados pero pobremente perfundidos, como en la embolia pulmonar o el bajo gasto cardiaco","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-187","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Parte del retorno venoso de la circulación bronquial drena directamente en las venas pulmonares sin pasar por el circuito pulmonar de intercambio. Este fenómeno explica, en parte, por qué:","respuesta":"La PaO2 arterial es ligeramente menor que la presión alveolar de oxígeno (gradiente A-a fisiológico)","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-188","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"La membrana alvéolo-capilar tiene un grosor aproximado de 0.4 micras. Esta característica anatómica favorece el intercambio gaseoso porque, según la ley de difusión de Fick, la velocidad de difusión de un gas es:","respuesta":"Inversamente proporcional al grosor de la membrana","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-189","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Los neumocitos tipo II comienzan a producir surfactante de forma significativa durante la fase sacular del desarrollo pulmonar. Esto explica por qué los recién nacidos prematuros de menos de 28-32 semanas tienen mayor riesgo de:","respuesta":"Enfermedad de membrana hialina por déficit de surfactante","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-190","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Durante la fase alveolar del desarrollo pulmonar, que se extiende desde el nacimiento hasta la niñez, el aumento del número de alvéolos tiene como consecuencia funcional principal:","respuesta":"El incremento progresivo del área de superficie disponible para el intercambio gaseoso","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-191","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un recién nacido de 24 semanas de gestación nace en apnea y requiere reanimación avanzada. Desde el punto de vista del desarrollo pulmonar, este paciente se encuentra en la transición entre las etapas canalicular y sacular. ¿Cuál es la implicación fisiológica más relevante de este hallazgo para su manejo respiratorio inmediato?","respuesta":"La capilarización alveolar y la producción de surfactante son aún mínimas, por lo que el riesgo de enfermedad de membrana hialina y colapso alveolar difuso es extremadamente alto","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-192","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En un paciente pediátrico con hemoptisis masiva de origen no traumático, el sangrado se origina con mayor frecuencia en la circulación bronquial y no en la circulación pulmonar. La explicación fisiológica de por qué la circulación bronquial es la fuente más probable es que:","respuesta":"Es un circuito de presión sistémica (mucho mayor que la presión pulmonar), por lo que un vaso bronquial lesionado sangra con mayor presión y volumen","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-193","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un neonato con hernia diafragmática congénita diagnosticada prenatalmente presenta hipoplasia pulmonar bilateral, con reducción del número de generaciones bronquiales y de la vascularización pulmonar. La compresión pulmonar por las vísceras herniadas interfiere principalmente con las etapas de desarrollo pulmonar que ocurren:","respuesta":"Durante los períodos pseudoglandular y canalicular, cuando se forma el árbol bronquial y se establece la capilarización","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-194","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Durante la ventilación mecánica con volúmenes corrientes elevados y PEEP alta, puede incrementarse el espacio muerto fisiológico. El mecanismo principal en este contexto es:","respuesta":"La sobredistensión alveolar comprime los capilares pulmonares adyacentes, generando unidades ventiladas pero mal perfundidas (similar a zona 1 de West)","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-195","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En un paciente con edema pulmonar intersticial grave, la distancia de difusión alvéolo-capilar (normalmente ~0.4 micras) se incrementa considerablemente. La consecuencia fisiológica esperada, según la ley de Fick, es:","respuesta":"Disminución de la velocidad de difusión de oxígeno, con hipoxemia que empeora característicamente durante el ejercicio o el estrés respiratorio Control de la Ventilación","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-196","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál estructura del tronco encefálico contiene el centro neumotáxico, encargado de inhibir la inspiración y regular la frecuencia respiratoria?","respuesta":"Protuberancia (puente)","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-197","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"El ritmo respiratorio básico se genera principalmente en:","respuesta":"El bulbo raquídeo, en los centros inspiratorio y espiratorio","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-198","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Los quimiorreceptores centrales, localizados en el bulbo raquídeo, responden principalmente a:","respuesta":"El incremento de hidrogeniones (H+) en el líquido cefalorraquídeo","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-199","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Los cuerpos carotídeos, principales quimiorreceptores periféricos, son los sensores más importantes para detectar:","respuesta":"La hipoxemia","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-200","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"El reflejo de Hering-Breuer se origina en receptores de estiramiento de adaptación lenta ubicados en la vía aérea, y su función principal es:","respuesta":"Evitar la sobredistensión pulmonar al inhibir la inspiración cuando el volumen pulmonar es muy grande","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-201","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"El centro apnéustico de la protuberancia tiende a prolongar la inspiración, mientras que el centro neumotáxico la limita. ¿Qué ocurre fisiológicamente cuando se lesiona o se inhibe el centro neumotáxico?","respuesta":"Se prolongan las inspiraciones, generando un patrón de respiración apnéustica","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-202","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Aunque los quimiorreceptores centrales responden al aumento de H+, el estímulo real que los activa de forma más eficiente es el CO2 sanguíneo y no el H+ plasmático directamente, porque:","respuesta":"El CO2 atraviesa fácilmente la barrera hematoencefálica, mientras que el H+ plasmático lo hace con dificultad","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-203","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Un paciente con enfermedad pulmonar crónica y retención crónica de CO2 puede depender, para mantener su impulso ventilatorio, principalmente de:","respuesta":"El estímulo hipóxico detectado por los quimiorreceptores periféricos, dado que sus quimiorreceptores centrales se han adaptado al CO2 elevado crónico","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-204","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"El reflejo de Hering-Breuer es más prominente y activo en el recién nacido que en el adulto sano en reposo. Esto se debe principalmente a que:","respuesta":"El neonato no tiene quimiorreceptores centrales funcionales","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-205","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Según el reflejo de Hering-Breuer descrito en la fisiología pulmonar, cuando se produce una espiración excesiva con riesgo de colapso pulmonar, la respuesta refleja esperada es:","respuesta":"Inhibición del centro espiratorio con predominio del centro inspiratorio","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-206","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un adolescente con intoxicación aguda por opioides presenta frecuencia respiratoria de 6 respiraciones/min, PaCO2 de 68 mmHg y PaO2 de 55 mmHg. La depresión respiratoria se debe principalmente a la acción de los opioides sobre:","respuesta":"Los centros respiratorios bulbares y pontinos, disminuyendo su respuesta a la hipercapnia","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-207","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"El síndrome de hipoventilación central congénita (síndrome de Ondina) se caracteriza por una respuesta ausente o marcadamente disminuida de los quimiorreceptores centrales a la hipercapnia, especialmente durante el sueño. Esto explica por qué estos pacientes presentan:","respuesta":"Episodios de hipoventilación grave durante el sueño con hipercapnia progresiva, mientras que la vigilia puede parcialmente compensarse con control voluntario cortical","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-208","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un paciente pediátrico con cardiopatía cianótica crónica y saturación basal de oxígeno de 78% presenta, con el tiempo, una respuesta ventilatoria menos intensa a nuevos episodios de hipoxia aguda que un niño sano. Esto se explica por:","respuesta":"La adaptación (embotamiento) de los quimiorreceptores periféricos a la hipoxemia crónica sostenida","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-209","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En un lactante ventilado mecánicamente con un volumen corriente excesivamente alto para su peso, se observa que el paciente presenta pausas respiratorias prolongadas al pasar a modo de ventilación espontánea. El mecanismo fisiológico más probable que contribuye a este hallazgo es:","respuesta":"Activación exagerada del reflejo de Hering-Breuer por sobredistensión pulmonar, que inhibe el impulso inspiratorio","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-210","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Durante una prueba de ventilación espontánea, un paciente con debilidad neuromuscular desarrolla taquipnea superficial progresiva y retención de CO2, a pesar de una respuesta adecuada de sus quimiorreceptores centrales y periféricos. Esto sugiere que la falla de la prueba se debe principalmente a:","respuesta":"Incapacidad de la bomba muscular respiratoria para traducir el impulso ventilatorio central en volumen corriente adecuado, no a un defecto en el control químico de la ventilación Mecánica Respiratoria","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-211","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"En reposo, al final de una espiración normal, ¿cuál es aproximadamente el valor de la presión pleural?","respuesta":"-5 cmH2O","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-212","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Al final de la inspiración y al final de la espiración, cuando no hay flujo de aire, la presión alveolar es:","respuesta":"Igual a la presión atmosférica (0 cmH2O relativo)","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-213","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"La presión transpulmonar se define como:","respuesta":"La diferencia entre la presión alveolar y la presión pleural","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-214","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"La distensibilidad (complianza) pulmonar se define como:","respuesta":"El cambio de volumen pulmonar por unidad de cambio de presión","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-215","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál es la función principal del agente surfactante producido por los neumocitos tipo II?","respuesta":"Disminuir la tensión superficial alveolar y mejorar la complianza pulmonar","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-216","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Durante la inspiración normal, la presión pleural disminuye desde aproximadamente -5 cmH2O hasta -7.5 cmH2O. El mecanismo que explica esta caída es:","respuesta":"La expansión de la caja torácica por contracción del diafragma y músculos inspiratorios, que aumenta la tracción elástica hacia afuera del pulmón","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-217","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Si un paciente en ventilación mecánica requiere un incremento notable de presión para lograr el mismo cambio de volumen corriente que antes, esto refleja principalmente:","respuesta":"Una disminución de la complianza pulmonar (pulmón más rígido)","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-218","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Según la ley de Poiseuille, la resistencia al flujo de aire en la vía aérea es inversamente proporcional a la cuarta potencia del radio. Clínicamente, esto explica por qué:","respuesta":"Pequeñas disminuciones del calibre de la vía aérea, como en el edema de la mucosa bronquial, incrementan drásticamente la resistencia al flujo","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-219","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"La constante de tiempo pulmonar (τ) se define como el producto de la resistencia de la vía aérea por la complianza pulmonar. Una unidad pulmonar con una constante de tiempo prolongada (por ejemplo, por resistencia elevada) requiere:","respuesta":"Más tiempo espiratorio para vaciarse completamente, con riesgo de atrapamiento aéreo si el tiempo disponible es insuficiente","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-220","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Según la ley de Laplace (P = 2T/r), en ausencia de surfactante, los alvéolos más pequeños generarían presiones de apertura mayores que los alvéolos grandes, lo que favorecería su colapso hacia los alvéolos de mayor tamaño. El surfactante evita este fenómeno porque:","respuesta":"Reduce más la tensión superficial en los alvéolos pequeños que en los grandes, igualando las presiones y estabilizando ambas poblaciones","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-221","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un niño de 6 años con estado asmático es intubado y ventilado mecánicamente. Minutos después presenta hipotensión progresiva, taquicardia y disminución del gasto cardiaco, sin evidencia de neumotórax. El ventilador muestra atrapamiento aéreo con auto-PEEP elevada. El mecanismo fisiopatológico de la hipotensión es:","respuesta":"El aumento de la presión intratorácica por atrapamiento aéreo disminuye el retorno venoso y el llenado ventricular derecho","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-222","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un lactante con bronquiolitis grave, ventilado con parámetros ajustados a una resistencia de vía aérea muy elevada (constante de tiempo prolongada), recibe tratamiento broncodilatador efectivo que reduce significativamente su resistencia. Si no se reajustan los parámetros ventilatorios, el principal riesgo es:","respuesta":"Que el tiempo espiratorio previamente programado (largo) resulte ahora excesivo, favoreciendo hipocapnia por sobreventilación con volúmenes corrientes mayores a los previstos","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-223","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En el SDRA, la complianza pulmonar está muy disminuida, lo que genera una constante de tiempo corta. A diferencia de un paciente con enfermedad obstructiva grave (constante de tiempo larga), el paciente con SDRA en ventilación mecánica generalmente requiere:","respuesta":"Tiempos inspiratorios y espiratorios relativamente cortos, ya que sus unidades pulmonares se llenan y vacían rápidamente, con riesgo de volutrauma más que de atrapamiento aéreo","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-224","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En un paciente ventilado en modo controlado por volumen, se observa un aumento de la presión pico inspiratoria mientras la presión meseta (plateau) permanece sin cambios. Este patrón sugiere que el problema se localiza principalmente en:","respuesta":"Un aumento de la resistencia de la vía aérea (por ejemplo, secreciones, broncoespasmo o acodamiento del tubo endotraqueal), sin cambios en la complianza pulmonar","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-225","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un adolescente con obesidad grave y aumento de la presión intraabdominal presenta presiones pleurales basales más elevadas (menos negativas) de lo habitual. Al calcular la presión transpulmonar (P alveolar - P pleural) durante la ventilación mecánica, esto tiene la siguiente implicación clínica:","respuesta":"Para lograr una presión transpulmonar adecuada que mantenga los alvéolos abiertos, puede requerirse una presión en la vía aérea (y PEEP) más alta que en un paciente sin esta condición Intercambio Gaseoso y Relación V/Q","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-226","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"En un pulmón sano, en promedio, ¿cuál es el valor global aproximado de la relación ventilación/perfusión (V/Q)?","respuesta":"0.8","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-227","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Cuando una unidad pulmonar está perfundida pero no ventilada, la relación V/Q es igual a:","respuesta":"Cero (efecto shunt)","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-228","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Cuando una unidad pulmonar está ventilada pero no perfundida, se dice que constituye:","respuesta":"Espacio muerto alveolar (V/Q infinito)","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-229","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"En posición de pie, en un pulmón sano, ¿en qué región es mayor la relación V/Q?","respuesta":"En el vértice (ápex) pulmonar","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-230","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Según el modelo de zonas de West, la base pulmonar en bipedestación corresponde predominantemente a:","respuesta":"Zona 3, con la mayor perfusión","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-231","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"En la zona 1 del modelo de West (PA > Pa > Pv), los capilares alveolares pueden colapsarse y la perfusión se reduce o se anula. Clínicamente, esta zona se favorece o se expande cuando:","respuesta":"Existe hipovolemia grave o se aplica una PEEP excesiva que eleva la presión alveolar","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-232","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"En bipedestación, tanto la ventilación como la perfusión aumentan desde el vértice hacia la base pulmonar por efecto de la gravedad, pero la relación V/Q termina siendo menor en la base. Esto se explica porque:","respuesta":"El aumento de la perfusión hacia la base es proporcionalmente mayor que el aumento de la ventilación","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-233","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Al aumentar la fracción inspirada de oxígeno (FiO2) administrada a un paciente, la presión alveolar de oxígeno (PAO2), calculada mediante la ecuación del gas alveolar, se modifica de forma:","respuesta":"Directamente proporcional al incremento de la FiO2, siempre que la presión barométrica y la PaCO2 se mantengan constantes","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-234","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Un paciente con hipoventilación global (por ejemplo, por depresión del centro respiratorio) presenta hipoxemia acompañada de hipercapnia, con una relación V/Q homogéneamente disminuida en todo el pulmón y sin alteración estructural del parénquima. ¿Qué característica distingue este mecanismo de hipoxemia de la causada por un mal V/Q localizado (como en la neumonía)?","respuesta":"La hipoxemia por hipoventilación pura se corrige fácilmente con oxígeno suplementario y se acompaña de hipercapnia proporcional","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-235","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"La ecuación de Bohr, empleada para estimar la fracción de espacio muerto fisiológico (VD/VT), se basa en la diferencia entre:","respuesta":"La PCO2 arterial y la PCO2 espirada mixta (medida en el gas espirado)","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-236","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un adolescente hospitalizado presenta disnea súbita, taquicardia e hipoxemia. La gasometría muestra PaCO2 de 32 mmHg, mientras que el CO2 espirado (EtCO2) medido por capnografía es de 18 mmHg, con un gradiente PaCO2-EtCO2 marcadamente aumentado. Este hallazgo es más compatible con:","respuesta":"Tromboembolismo pulmonar, que aumenta el espacio muerto alveolar (unidades ventiladas pero no perfundidas)","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-237","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En un lactante con SDRA grave en ventilación mecánica, la posición prona mejora la oxigenación. El mecanismo fisiológico principal por el cual la posición prona optimiza la relación V/Q es:","respuesta":"Redistribuye la ventilación hacia las zonas pulmonares dorsales, que en decúbito supino estaban colapsadas pero permanecen bien perfundidas, homogeneizando la relación V/Q","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-238","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un recién nacido cianótico no mejora su saturación de oxígeno (permanece en 65%) a pesar de recibir FiO2 al 100% durante la prueba de hiperoxia. Este resultado orienta hacia:","respuesta":"Un cortocircuito (shunt) verdadero, de origen cardiaco o pulmonar, en el cual la sangre no entra en contacto con alvéolos ventilados","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-239","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un lactante con displasia broncopulmonar grave presenta hiperinsuflación pulmonar con zonas de alta relación V/Q (espacio muerto funcional aumentado). Para mantener una PaCO2 adecuada, este paciente generalmente requiere:","respuesta":"Un volumen minuto mayor que el esperado para su edad, ya que una fracción importante de cada respiración no contribuye eficazmente a la eliminación de CO2","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-240","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En un paciente en choque hipovolémico que requiere ventilación mecánica con PEEP moderada-alta, existe mayor riesgo de conversión de zonas pulmonares perfundidas (zona 3) hacia zonas con perfusión reducida o ausente (zona 1 de West). La razón fisiológica es:","respuesta":"La hipovolemia reduce la presión venosa pulmonar (Pv) y arterial pulmonar (Pa), acercándolas o llevándolas por debajo de la presión alveolar elevada por la PEEP Transporte de Oxígeno","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-241","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál es la principal forma de transporte de oxígeno en la sangre?","respuesta":"Unido a la hemoglobina","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-242","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"El término P50 en la curva de disociación de la hemoglobina se refiere a:","respuesta":"La presión parcial de oxígeno a la cual la hemoglobina está saturada al 50%","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-243","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"La curva de disociación de la hemoglobina-oxígeno tiene forma sigmoidea. ¿Qué ventaja fisiológica confiere esta forma?","respuesta":"Permite una carga eficiente de O2 en el pulmón y una liberación eficiente en los tejidos","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-244","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"En comparación con la hemoglobina adulta, la hemoglobina fetal tiene:","respuesta":"Mayor afinidad por el oxígeno, lo que favorece la transferencia placentaria","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-245","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"La cantidad de oxígeno disuelto físicamente en el plasma (no unido a hemoglobina) depende principalmente de:","respuesta":"La presión parcial de oxígeno arterial","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-246","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"El efecto Bohr describe cómo el aumento local de CO2 e hidrogeniones en los tejidos periféricos:","respuesta":"Disminuye la afinidad de la hemoglobina por el oxígeno, favoreciendo su liberación hacia los tejidos","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-247","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"El efecto Haldane describe cómo la oxigenación de la hemoglobina a nivel pulmonar:","respuesta":"Disminuye la afinidad de la hemoglobina por el CO2 y los hidrogeniones, facilitando su liberación desde la sangre hacia el alvéolo","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-248","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Cuál de las siguientes combinaciones de condiciones desplaza la curva de disociación de la hemoglobina hacia la DERECHA, facilitando la liberación de oxígeno a los tejidos?","respuesta":"Acidosis, fiebre y aumento del 2,3-difosfoglicerato (2,3-DPG)","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-249","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"El contenido arterial de oxígeno (CaO2) se calcula fundamentalmente a partir de la hemoglobina, la saturación arterial de oxígeno y una pequeña fracción disuelta. De estos componentes, ¿cuál aporta la mayor parte del contenido total de oxígeno en condiciones normales?","respuesta":"El oxígeno unido a la hemoglobina","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-250","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"El aporte o disponibilidad de oxígeno a los tejidos (DO2) depende del contenido arterial de oxígeno y del gasto cardiaco. Si un paciente tiene una saturación de oxígeno normal pero un gasto cardiaco muy bajo (choque cardiogénico), lo más probable es que presente:","respuesta":"Disminución significativa del DO2 pese a una saturación arterial normal","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-251","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un lactante con choque séptico presenta fiebre de 39.5°C y acidosis metabólica con pH de 7.20. Respecto a un paciente afebril y con pH normal, para una misma PaO2, este lactante tendrá una saturación de oxígeno (SaO2):","respuesta":"Menor, porque la fiebre y la acidosis desplazan la curva de disociación de la hemoglobina hacia la derecha, disminuyendo la afinidad por el oxígeno","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-252","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un lactante recibe manejo con hipotermia terapéutica tras un paro cardiorrespiratorio. La hipotermia desplaza la curva de disociación de la hemoglobina hacia la izquierda. La implicación clínica de este desplazamiento es:","respuesta":"La hemoglobina retiene el oxígeno con mayor avidez, lo que puede dificultar su liberación a los tejidos periféricos pese a una SaO2 conservada","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-253","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un niño rescatado de un incendio presenta pulsioximetría de 98% pero se sospecha intoxicación por monóxido de carbono, confirmada posteriormente con carboxihemoglobina elevada. La razón por la que la pulsioximetría no refleja la gravedad real de la hipoxia tisular es que:","respuesta":"El pulsioxímetro no distingue entre oxihemoglobina y carboxihemoglobina, y además la carboxihemoglobina desplaza la curva de disociación hacia la izquierda, dificultando la liberación del oxígeno restante","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-254","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un niño en unidad de cuidados críticos tiene hemoglobina de 6 g/dL con SaO2 de 98% y PaO2 de 95 mmHg. Otro paciente tiene hemoglobina de 13 g/dL con SaO2 de 88%. Comparando el contenido arterial de oxígeno (CaO2) de ambos pacientes, es más probable que:","respuesta":"El paciente anémico con Hb de 6 g/dL tenga un CaO2 menor, a pesar de su saturación normal, porque el contenido de oxígeno depende fundamentalmente de la concentración de hemoglobina","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-255","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En un paciente en choque, la elevación progresiva del lactato sérico a pesar de una PaO2 y SaO2 normales sugiere que el aporte de oxígeno (DO2) ha caído por debajo del umbral crítico necesario para mantener el consumo de oxígeno (VO2) aeróbico. El determinante del DO2 que con mayor frecuencia está comprometido en el choque, incluso con oxigenación pulmonar preservada, es:","respuesta":"El gasto cardiaco Aplicación Clínica en Cuidados Críticos","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-256","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"La presión positiva al final de la espiración (PEEP) aplicada durante la ventilación mecánica tiene como objetivo principal:","respuesta":"Mantener los alvéolos abiertos y evitar su colapso al final de la espiración","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-257","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Fisiológicamente, una atelectasia produce hipoxemia porque genera unidades pulmonares con:","respuesta":"Relación V/Q baja o efecto shunt (perfusión sin ventilación)","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-258","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"La apnea del prematuro se relaciona principalmente con:","respuesta":"Inmadurez de los centros de control respiratorio y de la respuesta a la hipoxia/hipercapnia","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-259","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"En el síndrome de dificultad respiratoria aguda (SDRA), el principal cambio en la mecánica pulmonar es:","respuesta":"Disminución de la complianza pulmonar por edema e inflamación alveolar","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-260","tema":"fisiologia_pulmonar","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Un paciente con hipoxemia debida a una relación V/Q baja (por ejemplo, neumonía) generalmente responde a la administración de oxígeno suplementario. Esto contrasta con la hipoxemia por shunt verdadero, porque en el shunt:","respuesta":"La sangre no entra en contacto con alvéolos ventilados, por lo que aumentar la FiO2 tiene poco efecto","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-261","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"En el SDRA, la aplicación de PEEP busca mejorar la oxigenación principalmente porque:","respuesta":"Recluta alvéolos colapsados y aumenta la capacidad residual funcional, reduciendo el efecto shunt","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-262","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"En un lactante con bronquiolitis grave y broncoespasmo, la resistencia de la vía aérea está muy aumentada. Al programar la ventilación mecánica, esto obliga a:","respuesta":"Prolongar el tiempo espiratorio para permitir el vaciado pulmonar completo y evitar el atrapamiento aéreo","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-263","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"A diferencia del adulto, el recién nacido prematuro responde a la hipoxia con un patrón bifásico: un breve período de hiperventilación seguido de depresión respiratoria y apnea. Este comportamiento paradójico se debe a:","respuesta":"La inmadurez de los mecanismos centrales integradores, que no sostienen el estímulo hipóxico inicial de los quimiorreceptores periféricos","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-264","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Un paciente con atelectasia lobar completa presenta hipoxemia que mejora mínimamente al aumentar la FiO2 al 100%. Esto se explica porque la atelectasia se comporta fisiológicamente como:","respuesta":"Un shunt verdadero (V/Q = 0), donde la sangre no entra en contacto con alvéolos ventilados","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-265","tema":"fisiologia_pulmonar","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Al ajustar la PEEP en un paciente con SDRA, se busca un valor situado por encima del punto de inflexión inferior de la curva presión-volumen. El objetivo fisiológico de esto es:","respuesta":"Mantener los alvéolos reclutados sin llegar a la zona de sobredistensión de la curva","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-266","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un preescolar con neumonía viral grave presenta PaO2/FiO2 de 110 con PEEP de 8 cmH2O, infiltrados bilaterales en la radiografía de tórax y sin evidencia de sobrecarga hídrica que explique el cuadro. Este perfil es compatible con SDRA moderado. La fisiopatología predominante que explica su hipoxemia es:","respuesta":"Colapso alveolar difuso y edema inflamatorio que generan efecto shunt y disminución de la complianza pulmonar","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-267","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En un lactante con SDRA grave, se decide emplear una estrategia de ventilación protectora con volúmenes corrientes bajos (6 mL/kg), aceptando una PaCO2 de 65 mmHg con pH de 7.25 mediante hipercapnia permisiva. El fundamento fisiológico de esta estrategia es:","respuesta":"Limitar el volutrauma y el barotrauma pulmonar prioriza la protección del parénquima sobre la normalización estricta de la PaCO2, siempre que el pH se mantenga en un rango tolerable","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-268","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Los lactantes tienen una capacidad de cierre (closing capacity) que se superpone con su capacidad residual funcional (CRF) en mayor medida que los adultos, además de un consumo de oxígeno por kilogramo más elevado. Estas características explican por qué, durante la inducción anestésica o la intubación, los lactantes:","respuesta":"Desaturan más rápidamente ante episodios de apnea, debido a menor reserva de oxígeno (CRF baja en relación con su consumo) y mayor tendencia al colapso de la vía aérea pequeña","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-269","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un lactante con bronquiolitis en fase de resolución, previamente con resistencia de vía aérea elevada y auto-PEEP significativa, muestra ahora mejoría de la mecánica pulmonar con disminución de la resistencia y normalización de la constante de tiempo espiratoria. Antes de extubar, el equipo debe considerar principalmente que:","respuesta":"La mejoría de la mecánica pulmonar debe acompañarse de una adecuada fuerza muscular respiratoria y un impulso ventilatorio central intacto para sostener la ventilación espontánea, no solo de una buena constante de tiempo","source":"Banco de preguntas validado"},{"id":"fisiologia_pulmonar-270","tema":"fisiologia_pulmonar","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un recién nacido a término con síndrome de aspiración de meconio presenta hipoxemia refractaria, hipertensión pulmonar persistente con cortocircuito de derecha a izquierda a través del foramen oval, e inactivación secundaria del surfactante por el meconio. La combinación de estos mecanismos explica por qué este paciente presenta simultáneamente:","respuesta":"Componentes de shunt intrapulmonar (por inactivación de surfactante y atelectasia), shunt extrapulmonar (por hipertensión pulmonar) y baja complianza, lo que hace su hipoxemia particularmente refractaria a la oxigenoterapia","source":"Banco de preguntas validado"},{"id":"cardiopatias-271","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cómo se define una cardiopatía congénita?","respuesta":"Una anomalía estructural del corazón y/o de los grandes vasos que se origina durante el desarrollo embrionario","source":"Banco de preguntas validado"},{"id":"cardiopatias-272","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál es la incidencia aproximada de las cardiopatías congénitas en recién nacidos vivos?","respuesta":"8 a 10 por cada 1,000 nacidos vivos (aproximadamente 1%)","source":"Banco de preguntas validado"},{"id":"cardiopatias-273","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿En qué periodo del desarrollo embrionario ocurren con mayor frecuencia las alteraciones que originan las cardiopatías congénitas?","respuesta":"Durante el primer trimestre de la gestación","source":"Banco de preguntas validado"},{"id":"cardiopatias-274","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Según la clasificación de las cardiopatías congénitas por mecanismo (Nadas), ¿cuál de las siguientes opciones NO corresponde a una de sus categorías?","respuesta":"Cardiopatía restrictiva biventricular","source":"Banco de preguntas validado"},{"id":"cardiopatias-275","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Según la clasificación por mecanismo, ¿en qué grupo se ubica la tetralogía de Fallot?","respuesta":"Flujo pulmonar disminuido","source":"Banco de preguntas validado"},{"id":"cardiopatias-276","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál de las siguientes es un ejemplo clásico de cardiopatía con circulación pulmonar ductus-dependiente?","respuesta":"Atresia pulmonar","source":"Banco de preguntas validado"},{"id":"cardiopatias-277","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Cuáles son las estructuras embriológicas que forman el septum interauricular?","respuesta":"Septum primum, septum secundum, cojín endocárdico dorsal y la valva izquierda del seno venoso","source":"Banco de preguntas validado"},{"id":"cardiopatias-278","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Qué cardiopatía congénita se asocia con mayor frecuencia al síndrome de Down (trisomía 21)?","respuesta":"El defecto septal auriculoventricular (canal AV) y la CIA tipo ostium primum","source":"Banco de preguntas validado"},{"id":"cardiopatias-279","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"El síndrome de DiGeorge (microdeleción 22q11) se asocia con mayor frecuencia a cardiopatías de origen:","respuesta":"Conotruncal, como la tetralogía de Fallot y el truncus arterioso","source":"Banco de preguntas validado"},{"id":"cardiopatias-280","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"En la secuencia VACTERL, ¿qué representa la letra 'C'?","respuesta":"Defectos cardíacos","source":"Banco de preguntas validado"},{"id":"cardiopatias-281","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"¿Cuál de las siguientes afirmaciones sobre la clasificación de cardiopatías congénitas por mecanismo es FALSA?","respuesta":"Todas las cardiopatías con cortocircuito de izquierda a derecha cursan con cianosis marcada desde el nacimiento","source":"Banco de preguntas validado"},{"id":"cardiopatias-282","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"¿Qué línea celular embriológica está implicada en el desarrollo de los defectos conotruncales (como la tetralogía de Fallot o el truncus arterioso) y explica su asociación con el síndrome de DiGeorge?","respuesta":"Las células de la cresta neural cardíaca","source":"Banco de preguntas validado"},{"id":"cardiopatias-283","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un lactante con atresia tricuspídea y un solo ventrículo funcional se clasifica, según el mecanismo fisiopatológico, dentro del grupo de:","respuesta":"Corazón univentricular Cortocircuitos Izquierda-Derecha (CIA/CIV/PCA)","source":"Banco de preguntas validado"},{"id":"cardiopatias-284","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"La comunicación interauricular (CIA) se define como:","respuesta":"Un defecto del septo interauricular que comunica de forma anómala la aurícula derecha con la izquierda","source":"Banco de preguntas validado"},{"id":"cardiopatias-285","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Qué porcentaje aproximado del total de cardiopatías congénitas representa la comunicación interauricular?","respuesta":"10% a 15%","source":"Banco de preguntas validado"},{"id":"cardiopatias-286","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál es el tipo anatómico más frecuente de comunicación interauricular?","respuesta":"Ostium secundum","source":"Banco de preguntas validado"},{"id":"cardiopatias-287","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál es la cardiopatía congénita más frecuente en la población pediátrica?","respuesta":"Comunicación interventricular","source":"Banco de preguntas validado"},{"id":"cardiopatias-288","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Según su localización anatómica, ¿cuál es el tipo más frecuente de comunicación interventricular?","respuesta":"Perimembranosa","source":"Banco de preguntas validado"},{"id":"cardiopatias-289","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"El conducto arterioso (ductus arterioso), en condiciones normales, comunica:","respuesta":"La porción distal del arco aórtico con la porción proximal de la arteria pulmonar izquierda","source":"Banco de preguntas validado"},{"id":"cardiopatias-290","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Por qué los cortocircuitos de izquierda a derecha como la CIV no producen cianosis?","respuesta":"Porque la sangre oxigenada pasa del lado izquierdo (mayor presión) hacia el derecho, sin que sangre desaturada entre a la circulación sistémica","source":"Banco de preguntas validado"},{"id":"cardiopatias-291","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"El hallazgo característico en el examen físico de un paciente con CIA es:","respuesta":"Un soplo eyectivo en el segundo espacio intercostal izquierdo con desdoblamiento fijo del segundo ruido","source":"Banco de preguntas validado"},{"id":"cardiopatias-292","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"El hallazgo electrocardiográfico característico de la comunicación interauricular es:","respuesta":"Bloqueo incompleto de rama derecha (patrón rSR' en V1)","source":"Banco de preguntas validado"},{"id":"cardiopatias-293","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Cuál es el hallazgo típico en el examen físico de un lactante con CIV moderada a grande?","respuesta":"Cardiomegalia y soplo holosistólico en el borde esternal izquierdo, con posible refuerzo del componente pulmonar del segundo ruido","source":"Banco de preguntas validado"},{"id":"cardiopatias-294","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"El soplo característico de la persistencia del conducto arterioso se describe como:","respuesta":"Sistodiastólico continuo, 'en maquinaria', en el foco pulmonar o la región infraclavicular izquierda","source":"Banco de preguntas validado"},{"id":"cardiopatias-295","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un adolescente con antecedente de CIV grande nunca corregida presenta ahora cianosis, poliglobulia e hipocratismo digital. ¿Cuál es el mecanismo fisiopatológico más probable?","respuesta":"Desarrollo de enfermedad vascular pulmonar irreversible con inversión del cortocircuito a derecha-izquierda (síndrome de Eisenmenger)","source":"Banco de preguntas validado"},{"id":"cardiopatias-296","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En un prematuro con PCA hemodinámicamente significativo y falla en el cierre farmacológico con indometacina o ibuprofeno, la siguiente opción terapéutica es:","respuesta":"Cierre quirúrgico o por cateterismo percutáneo del conducto arterioso Flujo Pulmonar Disminuido (Fallot)","source":"Banco de preguntas validado"},{"id":"cardiopatias-297","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál es la cardiopatía congénita cianótica más frecuente?","respuesta":"Tetralogía de Fallot","source":"Banco de preguntas validado"},{"id":"cardiopatias-298","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál de las siguientes NO forma parte de los cuatro componentes clásicos de la tetralogía de Fallot?","respuesta":"Estenosis mitral congénita","source":"Banco de preguntas validado"},{"id":"cardiopatias-299","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál es la incidencia aproximada de la tetralogía de Fallot?","respuesta":"3 a 6 por cada 10,000 nacidos vivos","source":"Banco de preguntas validado"},{"id":"cardiopatias-300","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Quién describió por primera vez la tétrada de anomalías cardíacas que hoy lleva su nombre?","respuesta":"Etienne-Louis Arthur Fallot","source":"Banco de preguntas validado"},{"id":"cardiopatias-301","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"La acropaquia o 'dedos en palillo de tambor' es un hallazgo típico asociado a:","respuesta":"Cardiopatías con disminución crónica del flujo pulmonar y cianosis","source":"Banco de preguntas validado"},{"id":"cardiopatias-302","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"En la tetralogía de Fallot, el grado de cianosis depende principalmente de:","respuesta":"El grado de obstrucción del tracto de salida del ventrículo derecho, que determina la magnitud del cortocircuito de derecha a izquierda a través de la CIV","source":"Banco de preguntas validado"},{"id":"cardiopatias-303","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Las 'crisis de hipoxia' (tet spells) en la tetralogía de Fallot se producen por:","respuesta":"Un aumento súbito de la obstrucción dinámica infundibular y/o una caída de la resistencia vascular sistémica, que incrementan el cortocircuito de derecha a izquierda","source":"Banco de preguntas validado"},{"id":"cardiopatias-304","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"El hallazgo radiológico clásico en la tetralogía de Fallot, descrito como 'corazón en bota sueca', se debe a:","respuesta":"La hipertrofia del ventrículo derecho con elevación de la punta cardíaca y un segmento pulmonar cóncavo por hipoflujo pulmonar","source":"Banco de preguntas validado"},{"id":"cardiopatias-305","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Según los datos epidemiológicos revisados, ¿en qué proporción aproximada de pacientes con tetralogía de Fallot se encuentra el síndrome de DiGeorge?","respuesta":"Aproximadamente el 20%","source":"Banco de preguntas validado"},{"id":"cardiopatias-306","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Qué porcentaje aproximado de pacientes con tetralogía de Fallot presenta un arco aórtico desplazado hacia la derecha?","respuesta":"Aproximadamente el 25%","source":"Banco de preguntas validado"},{"id":"cardiopatias-307","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un lactante con tetralogía de Fallot presenta una crisis de hipoxia (tet spell) con cianosis intensa y llanto inconsolable. ¿Cuál es la medida inicial más adecuada?","respuesta":"Colocarlo en posición genupectoral (rodillas al pecho), administrar oxígeno y considerar morfina para calmar el llanto","source":"Banco de preguntas validado"},{"id":"cardiopatias-308","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En un lactante con tetralogía de Fallot que presenta crisis de hipoxia recurrentes antes del año de edad y que no es candidato inmediato a corrección total, la conducta quirúrgica habitual es:","respuesta":"Realizar una fístula sistémico-pulmonar (Blalock-Taussig) como paliación","source":"Banco de preguntas validado"},{"id":"cardiopatias-309","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un lactante de 8 meses con cianosis progresiva, soplo sistólico rudo en el borde esternal izquierdo alto y radiografía de tórax con 'corazón en bota sueca' es diagnosticado por ecocardiograma con tetralogía de Fallot no complicada. Según lo revisado, ¿en qué rango de edad se acepta habitualmente realizar la corrección quirúrgica total?","respuesta":"Entre los dos y cinco años de edad Circulación Ductus-Dependiente y en Paralelo","source":"Banco de preguntas validado"},{"id":"cardiopatias-310","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"En las cardiopatías con circulación pulmonar ductus-dependiente, el síntoma cardinal es:","respuesta":"La cianosis","source":"Banco de preguntas validado"},{"id":"cardiopatias-311","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál es el ejemplo clásico de cardiopatía con fisiología de 'circulación en paralelo'?","respuesta":"Transposición de grandes arterias","source":"Banco de preguntas validado"},{"id":"cardiopatias-312","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"En la transposición de grandes arterias, se describe la fisiología como '2 circuitos en paralelo' porque:","respuesta":"La sangre sistémica y la pulmonar circulan de forma separada, sin mezclarse entre sí","source":"Banco de preguntas validado"},{"id":"cardiopatias-313","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Para que un recién nacido con transposición de grandes arterias pueda sobrevivir, es indispensable que exista:","respuesta":"Un sitio de mezcla entre ambas circulaciones (CIA, CIV o PCA)","source":"Banco de preguntas validado"},{"id":"cardiopatias-314","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Las cardiopatías con circulación ductus-dependiente se dividen fisiopatológicamente en dos grupos según el flujo que depende del ductus. ¿Cuáles son?","respuesta":"Ductus-dependientes de flujo pulmonar (ej. atresia pulmonar) y ductus-dependientes de flujo sistémico (ej. síndrome de corazón izquierdo hipoplásico)","source":"Banco de preguntas validado"},{"id":"cardiopatias-315","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"El procedimiento de Rashkind, realizado en sala de cateterismo en pacientes con transposición de grandes arterias, consiste en:","respuesta":"Una septostomía auricular con balón para ampliar la comunicación interauricular y mejorar la mezcla sanguínea","source":"Banco de preguntas validado"},{"id":"cardiopatias-316","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"¿Cuál es la diferencia fisiopatológica fundamental entre la D-transposición y la L-transposición de grandes arterias?","respuesta":"En la D-transposición la discordancia es únicamente ventrículo-arterial y produce cianosis grave; en la L- transposición ('corregida') existe además discordancia auriculoventricular que compensa parcialmente la circulación","source":"Banco de preguntas validado"},{"id":"cardiopatias-317","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"El mecanismo de acción de la prostaglandina E1 para mantener el conducto arterioso permeable es:","respuesta":"Relajar el músculo liso de la pared ductal, evitando su constricción","source":"Banco de preguntas validado"},{"id":"cardiopatias-318","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"La cirugía de Jatene (switch arterial) para la transposición de grandes arterias se realiza idealmente:","respuesta":"En las primeras dos a tres semanas de vida, antes de que el ventrículo izquierdo se 'desacondicione' al circuito de baja presión pulmonar","source":"Banco de preguntas validado"},{"id":"cardiopatias-319","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un recién nacido de horas de vida presenta cianosis central que no mejora al administrar oxígeno al 100% (prueba de hiperoxia negativa). Esto sugiere que la causa de la cianosis es:","respuesta":"De origen cardíaco, con un cortocircuito de derecha a izquierda fijo, más que de origen pulmonar","source":"Banco de preguntas validado"},{"id":"cardiopatias-320","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un recién nacido con transposición de grandes arterias se mantiene con infusión de prostaglandina E1, pero persiste con saturación de oxígeno crítica a pesar de un ductus permeable por ecocardiograma. ¿Cuál es el siguiente paso más adecuado?","respuesta":"Realizar una septostomía auricular con balón (procedimiento de Rashkind) en sala de cateterismo","source":"Banco de preguntas validado"},{"id":"cardiopatias-321","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un neonato con síndrome de corazón izquierdo hipoplásico (circulación sistémica ductus-dependiente) se encuentra hipotenso y con mala perfusión. Administrar oxígeno suplementario en exceso en este contexto puede ser perjudicial porque:","respuesta":"Disminuye la resistencia vascular pulmonar, favoreciendo que más flujo sanguíneo se desvíe hacia el pulmón a expensas del flujo sistémico","source":"Banco de preguntas validado"},{"id":"cardiopatias-322","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Antes de trasladar a un recién nacido con cardiopatía ductus-dependiente en infusión de prostaglandina E1 hacia un centro de referencia, es indispensable prever la posibilidad de:","respuesta":"Apnea inducida por la prostaglandina, por lo que debe garantizarse la capacidad de manejo avanzado de la vía aérea durante el traslado Obstrucciones Izquierdas","source":"Banco de preguntas validado"},{"id":"cardiopatias-323","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuáles son ejemplos clásicos de cardiopatías del grupo de obstrucciones izquierdas?","respuesta":"Estenosis aórtica crítica y coartación de aorta","source":"Banco de preguntas validado"},{"id":"cardiopatias-324","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Las obstrucciones izquierdas son la primera causa de insuficiencia cardíaca en neonatos y lactantes; por ello, en todo neonato con falla cardíaca es obligatorio explorar:","respuesta":"Los pulsos femorales","source":"Banco de preguntas validado"},{"id":"cardiopatias-325","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"La coartación de aorta se define como:","respuesta":"Un estrechamiento congénito de la luz aórtica, más frecuente en la región yuxtaductal","source":"Banco de preguntas validado"},{"id":"cardiopatias-326","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"El tratamiento de elección para la estenosis aórtica crítica del neonato es:","respuesta":"La dilatación de la válvula aórtica por cateterismo (valvuloplastia con balón)","source":"Banco de preguntas validado"},{"id":"cardiopatias-327","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"En la coartación de aorta crítica del neonato, el deterioro clínico brusco que ocurre en los primeros días de vida se explica por:","respuesta":"El cierre del conducto arterioso, que era la vía que suplía flujo sanguíneo a la aorta descendente sorteando la obstrucción","source":"Banco de preguntas validado"},{"id":"cardiopatias-328","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"La coartación de aorta se asocia con frecuencia a:","respuesta":"Hipoplasia del arco aórtico","source":"Banco de preguntas validado"},{"id":"cardiopatias-329","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"El manejo de la coartación de aorta crítica del neonato incluye:","respuesta":"Prostaglandinas para reabrir el ductus, seguidas de dilatación por cateterismo o coartectomía quirúrgica","source":"Banco de preguntas validado"},{"id":"cardiopatias-330","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"En un lactante con coartación de aorta no crítica, el hallazgo clínico esperado en la toma de presión arterial es:","respuesta":"Presión arterial mayor en miembros superiores que en miembros inferiores, con pulsos femorales débiles o retrasados","source":"Banco de preguntas validado"},{"id":"cardiopatias-331","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un recién nacido con estenosis aórtica crítica se presenta en shock cardiogénico con pulsos débiles generalizados. El manejo inicial de estabilización debe incluir:","respuesta":"Infusión de prostaglandina E1 para mantener el conducto arterioso permeable y así sostener parte del flujo sistémico","source":"Banco de preguntas validado"},{"id":"cardiopatias-332","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un lactante de 10 días de vida previamente sano presenta letargia, mala perfusión distal, hepatomegalia y acidosis metabólica, con pulsos femorales ausentes. Antes de asumir únicamente un cuadro séptico, la sospecha diagnóstica prioritaria debe ser:","respuesta":"Coartación de aorta crítica con cierre del conducto arterioso","source":"Banco de preguntas validado"},{"id":"cardiopatias-333","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En un neonato con coartación de aorta crítica asociada a hipoplasia importante del arco aórtico, la conducta quirúrgica más adecuada suele ser:","respuesta":"La reparación quirúrgica (coartectomía con ampliación del arco), más que la dilatación aislada por catéter, dado que esta última no corrige la hipoplasia asociada","source":"Banco de preguntas validado"},{"id":"cardiopatias-334","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"¿Cuál de las siguientes afirmaciones sobre las obstrucciones izquierdas es FALSA?","respuesta":"La estenosis aórtica crítica y la coartación de aorta son causas poco frecuentes de insuficiencia cardíaca neonatal Hipertensión Venosa Pulmonar","source":"Banco de preguntas validado"},{"id":"cardiopatias-335","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"¿Cuál de las siguientes es un ejemplo del grupo de cardiopatías con hipertensión venosa pulmonar?","respuesta":"Conexión venosa pulmonar anómala total obstruida","source":"Banco de preguntas validado"},{"id":"cardiopatias-336","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"De todas las cardiopatías congénitas, ¿cuál se considera la única verdadera emergencia quirúrgica?","respuesta":"La conexión venosa pulmonar anómala total obstruida","source":"Banco de preguntas validado"},{"id":"cardiopatias-337","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"Clínicamente, un recién nacido con conexión venosa pulmonar anómala total obstruida puede confundirse con un cuadro de:","respuesta":"Neumonía","source":"Banco de preguntas validado"},{"id":"cardiopatias-338","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Las medidas generales de estabilización antes de llevar a cirugía a un neonato con CVAPT obstruida incluyen:","respuesta":"Intubación con ventilación mecánica, sedación, analgesia y mantenimiento de la presión arterial","source":"Banco de preguntas validado"},{"id":"cardiopatias-339","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"El signo radiológico conocido como 'muñeco de nieve' se asocia clásicamente a:","respuesta":"La conexión venosa pulmonar anómala total de tipo supracardíaco","source":"Banco de preguntas validado"},{"id":"cardiopatias-340","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"En la CVAPT obstruida, la dificultad respiratoria grave del recién nacido se explica porque:","respuesta":"Las venas pulmonares no logran drenar hacia la aurícula izquierda por la obstrucción, generando congestión y edema del lecho vascular pulmonar","source":"Banco de preguntas validado"},{"id":"cardiopatias-341","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Además de la CVAPT obstruida, ¿qué otra entidad pertenece al grupo de hipertensión venosa pulmonar?","respuesta":"La estenosis mitral congénita","source":"Banco de preguntas validado"},{"id":"cardiopatias-342","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un recién nacido con conexión venosa pulmonar anómala total de tipo infradiafragmático (infracardíaco) presenta dificultad respiratoria grave de inicio temprano. En este subtipo, a diferencia del tipo supracardíaco no obstruido, es característico encontrar:","respuesta":"Obstrucción venosa grave con edema pulmonar intenso y silueta cardíaca de tamaño normal o pequeño","source":"Banco de preguntas validado"},{"id":"cardiopatias-343","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un recién nacido con diagnóstico ecocardiográfico de CVAPT obstruida se encuentra en dificultad respiratoria progresiva a pesar de intubación, ventilación mecánica, sedación y soporte hemodinámico óptimo. La conducta correcta es:","respuesta":"Llevarlo a sala de operaciones para corrección quirúrgica urgente, ya que no existe tratamiento médico definitivo para la obstrucción","source":"Banco de preguntas validado"},{"id":"cardiopatias-344","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un recién nacido a término presenta dificultad respiratoria progresiva, hipoxemia refractaria e infiltrados difusos bilaterales, con ecocardiograma que sugiere obstrucción del retorno venoso pulmonar. El error diagnóstico más peligroso en este contexto sería:","respuesta":"Tratarlo únicamente como una neumonía neonatal y retrasar la evaluación quirúrgica urgente","source":"Banco de preguntas validado"},{"id":"cardiopatias-345","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En la estenosis mitral congénita, el mecanismo por el cual se produce hipertensión venosa pulmonar es:","respuesta":"La obstrucción al vaciamiento de la aurícula izquierda genera un aumento retrógrado de presión en las venas y el lecho capilar pulmonar","source":"Banco de preguntas validado"},{"id":"cardiopatias-346","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un neonato con dificultad respiratoria grave e hipoxemia recibe una prueba terapéutica con prostaglandina E1 sin ninguna mejoría clínica. Este hallazgo es compatible con:","respuesta":"Una causa no ductus-dependiente, como la CVAPT obstruida, en la que el problema es el drenaje venoso pulmonar y no el flujo a través del ductus","source":"Banco de preguntas validado"},{"id":"cardiopatias-347","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"A diferencia de las cardiopatías con circulación ductus-dependiente, en la CVAPT obstruida:","respuesta":"Mantener el conducto arterioso abierto con prostaglandina E1 no resuelve el problema fisiopatológico de fondo, que es la obstrucción del retorno venoso pulmonar Manejo y Tratamiento","source":"Banco de preguntas validado"},{"id":"cardiopatias-348","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"En un recién nacido con sospecha de cardiopatía congénita ductus-dependiente, el objetivo principal del tratamiento inicial es:","respuesta":"Mantener el conducto arterioso permeable","source":"Banco de preguntas validado"},{"id":"cardiopatias-349","tema":"cardiopatias","difficulty":"bajo","subtema":"Repaso clínico","pregunta":"En las cardiopatías con circulación pulmonar ductus-dependiente, el uso de oxígeno suplementario a altas concentraciones:","respuesta":"Está contraindicado porque favorece el cierre del conducto arterioso","source":"Banco de preguntas validado"},{"id":"cardiopatias-350","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Una de las indicaciones para el cierre quirúrgico o percutáneo de una CIA es:","respuesta":"Una relación de flujo pulmonar/sistémico (Qp/Qs) mayor de 1.5:1","source":"Banco de preguntas validado"},{"id":"cardiopatias-351","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"Según lo revisado, la edad generalmente aceptada para realizar el cierre electivo de una CIA es:","respuesta":"Entre los tres y cinco años de edad","source":"Banco de preguntas validado"},{"id":"cardiopatias-352","tema":"cardiopatias","difficulty":"medio","subtema":"Repaso clínico","pregunta":"En pacientes con tetralogía de Fallot que requieren una intervención paliativa temprana (antes del año de edad), el procedimiento habitual es:","respuesta":"Una fístula sistémico-pulmonar (tipo Blalock-Taussig)","source":"Banco de preguntas validado"},{"id":"cardiopatias-353","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un recién nacido cianótico es valorado en urgencias. ¿En cuál de los siguientes escenarios NO está indicado iniciar oxígeno suplementario de forma liberal como primera medida?","respuesta":"Sospecha de cardiopatía congénita ductus-dependiente o de circulación en paralelo","source":"Banco de preguntas validado"},{"id":"cardiopatias-354","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un lactante con una CIV moderada es evaluado por cateterismo cardíaco, encontrándose una relación de flujo pulmonar/sistémico (Qp/Qs) de 2.2:1 con signos clínicos de sobrecarga de volumen. Esto constituye:","respuesta":"Una indicación de cierre quirúrgico del defecto","source":"Banco de preguntas validado"},{"id":"cardiopatias-355","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"En un lactante con tetralogía de Fallot y arterias pulmonares severamente hipoplásicas, la estrategia quirúrgica más adecuada suele ser:","respuesta":"Realizar primero una fístula sistémico-pulmonar paliativa para promover el crecimiento de las arterias pulmonares antes de la corrección total","source":"Banco de preguntas validado"},{"id":"cardiopatias-356","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"A diferencia de la CIA, que habitualmente se cierra de forma electiva entre los tres y cinco años de edad, una CIV grande con insuficiencia cardíaca congestiva y falla de medro en un lactante de 4 meses debe manejarse mediante:","respuesta":"Cierre quirúrgico más temprano, sin esperar a la edad electiva habitual de la CIA, dado el compromiso hemodinámico actual","source":"Banco de preguntas validado"},{"id":"cardiopatias-357","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un residente debe decidir el manejo del conducto arterioso en dos pacientes distintos: un prematuro con PCA hemodinámicamente significativo y un recién nacido a término con atresia pulmonar. La conducta correcta es:","respuesta":"Buscar el cierre del ductus en el prematuro con PCA sintomático, y mantenerlo abierto con prostaglandina E1 en el neonato con atresia pulmonar","source":"Banco de preguntas validado"},{"id":"cardiopatias-358","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un recién nacido de 6 horas de vida presenta cianosis progresiva, un segundo ruido único y fuerte, sin soplo audible, y una radiografía de tórax con silueta cardíaca en 'huevo colgado de un hilo'. El manejo inicial más apropiado incluye:","respuesta":"Iniciar prostaglandina E1, evitar oxígeno en concentraciones altas y preparar traslado a un centro con capacidad de cateterismo (Rashkind) y cirugía de Jatene","source":"Banco de preguntas validado"},{"id":"cardiopatias-359","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un niño de 4 años con CIA tipo ostium primum grande es evaluado para el cierre del defecto. La vía de cierre más adecuada en este caso es:","respuesta":"El cierre quirúrgico, ya que los defectos tipo ostium primum no son candidatos habituales para el cierre percutáneo con dispositivo","source":"Banco de preguntas validado"},{"id":"cardiopatias-360","tema":"cardiopatias","difficulty":"alto","subtema":"Repaso clínico","pregunta":"Un recién nacido de 3 días de vida, previamente asintomático, presenta deterioro súbito con mala perfusión, pulsos débiles generalizados, hepatomegalia y acidosis metabólica progresiva, con saturación preductal y posductal similares. Antes de tener disponible un ecocardiograma, la conducta más prudente es:","respuesta":"Iniciar empíricamente infusión de prostaglandina E1, ante la sospecha de una cardiopatía ductus-dependiente, mientras se organiza el estudio ecocardiográfico","source":"Banco de preguntas validado"}];
